create function public.pro_save_workspace(p_user uuid,p_document jsonb,p_revision integer) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v integer;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 select revision into v from pro_workspaces where user_id=p_user for update;
 if coalesce(v,0)<>p_revision then raise exception 'revision conflict' using errcode='40001'; end if;
 v:=coalesce(v,0)+1;
 insert into pro_workspaces(user_id,document,revision) values(p_user,p_document,v)
 on conflict(user_id) do update set document=excluded.document,revision=excluded.revision,updated_at=now();
 return v;
end $$;
create function public.pro_request_social(p_user uuid,p_id uuid,p_title text,p_link text,p_description text) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r pro_social_requests;
begin
 insert into pro_social_requests(id,user_id,month,title,link,description)
 values(p_id,p_user,to_char(now() at time zone 'America/Costa_Rica','YYYY-MM'),p_title,p_link,p_description) returning * into r;
 insert into pro_audit(actor,subject,action,detail) values(p_user,p_user,'social.request',jsonb_build_object('id',p_id));
 return to_jsonb(r);
end $$;
create function public.pro_review_social(p_actor uuid,p_id uuid,p_status text,p_note text,p_url text) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
declare r pro_social_requests;
begin
 if not exists(select 1 from profiles where id=p_actor and role='admin' and coalesce(is_disabled,false)=false) then raise exception 'admin required'; end if;
 select * into strict r from pro_social_requests where id=p_id for update;
 if not ((r.status='pending' and p_status in ('approved','rejected')) or (r.status='approved' and p_status='published')) then raise exception 'invalid transition'; end if;
 if (p_status='rejected' and length(trim(p_note))=0) or (p_status='published' and p_url not like 'https://%') then raise exception 'missing reason or url'; end if;
 update pro_social_requests set status=p_status,note=p_note,published_url=p_url,updated_at=now() where id=p_id;
 insert into pro_audit(actor,subject,action,detail) values(p_actor,r.user_id,'social.'||p_status,jsonb_build_object('id',p_id,'note',p_note,'url',p_url));
end $$;
create function public.pro_set_membership(p_actor uuid,p_user uuid,p_status text,p_expires timestamptz,p_reason text) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if not exists(select 1 from profiles where id=p_actor and role='admin' and coalesce(is_disabled,false)=false) then raise exception 'admin required'; end if;
 if length(trim(p_reason))=0 then raise exception 'reason required'; end if;
 insert into pro_memberships(user_id,status,expires_at) values(p_user,p_status,p_expires)
 on conflict(user_id) do update set status=excluded.status,expires_at=excluded.expires_at,updated_at=now();
 insert into pro_audit(actor,subject,action,detail) values(p_actor,p_user,'membership.'||p_status,jsonb_build_object('expiresAt',p_expires,'reason',p_reason));
end $$;
revoke all on function public.pro_save_workspace(uuid,jsonb,integer),public.pro_request_social(uuid,uuid,text,text,text),public.pro_review_social(uuid,uuid,text,text,text),public.pro_set_membership(uuid,uuid,text,timestamptz,text) from public,anon,authenticated;
grant execute on function public.pro_save_workspace(uuid,jsonb,integer),public.pro_request_social(uuid,uuid,text,text,text),public.pro_review_social(uuid,uuid,text,text,text),public.pro_set_membership(uuid,uuid,text,timestamptz,text) to service_role;

$pro_install$; end if; end $pro_guard$;

-- ===== pro-entitled-draft.sql =====
-- LOCAL DRAFT (multivertical F3, 2026-11-16). NOT WIRED: no existing module calls these yet. Plan to replace the six
-- copies of the Pro access rule is in the session wiring notes (dir-wiring-F3F5.md).
-- * pro_entitled(actor): single SQL mirror of hasProAccess (src/lib/pro/access.ts) plus the ban check used by
--   work-changes / private-work-tools / appointment-requests. Enabled admin -> true; professional or provider with
--   an active grant whose expiry is null or a finite future instant -> true; disabled or banned -> false.
-- * Expiry uses clock_timestamp(): a grant that expires while a request waits on a row lock must be refused after the wait.
-- * pro_entitled_require(actor): raises 42501 (same error the six modules raise today).
-- * pro_membership_grant_launch_free(staff, user): launch grant (Pro free at launch). Idempotent: never touches
--   an existing grant row (active or inactive); writes pro_audit 'membership.launch_free'. It is unrelated to the
--   public directory: claims, verification and ranking never read it.
-- Depends on profiles, professionals, pro_memberships, pro_audit (memberships-draft.sql).
begin;
create or replace function public.pro_entitled(p_actor uuid) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(exists(select 1 from profiles p left join pro_memberships m on m.user_id=p.id
   where p.id=p_actor and not coalesce(p.is_disabled,false)
    and (p.role='admin' or ((p.role='professional' or coalesce(p.is_provider,false)) and m.status='active'
     and (m.expires_at is null or (isfinite(m.expires_at) and m.expires_at>clock_timestamp())))))
  and not exists(select 1 from professionals x where x.profile_id=p_actor and coalesce(x.is_banned,false)),false) $$;

create or replace function public.pro_entitled_require(p_actor uuid) returns void
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin if not public.pro_entitled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;end $$;

create or replace function public.pro_membership_grant_launch_free(p_actor uuid,p_user uuid) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare n integer;granted boolean;
begin
 if p_actor is null or p_user is null then raise exception 'Invalid grant' using errcode='22023';end if;
 if not exists(select 1 from profiles where id=p_user and not coalesce(is_disabled,false) and (role='professional' or coalesce(is_provider,false))) then
  raise exception 'Not eligible' using errcode='22023',hint='pro_launch_not_eligible';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-membership:'||p_user::text,0));
 insert into pro_memberships(user_id,status,expires_at) values(p_user,'active',null) on conflict(user_id) do nothing;
 get diagnostics n=row_count;granted:=n>0;
 if granted then insert into pro_audit(actor,subject,action,detail) values(p_actor,p_user,'membership.launch_free',jsonb_build_object('source','launch_free'));end if;
 return jsonb_build_object('userId',p_user,'granted',granted);
end $$;

revoke all on function public.pro_entitled(uuid),public.pro_entitled_require(uuid),public.pro_membership_grant_launch_free(uuid,uuid) from public,anon,authenticated;
grant execute on function public.pro_entitled(uuid),public.pro_entitled_require(uuid),public.pro_membership_grant_launch_free(uuid,uuid) to service_role;
commit;

