alter table public.pro_panel_legacy_backup enable row level security;
revoke all on public.pro_panel_legacy_backup from public,anon,authenticated;
grant all on public.pro_panel_legacy_backup to service_role;
revoke all on function public.pro_upsert_panels(uuid,jsonb),public.pro_store_panels(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_upsert_panels(uuid,jsonb),public.pro_store_panels(uuid,jsonb) to service_role;
revoke all on function public.pro_legacy_quote_record(uuid,text) from public,anon;
grant execute on function public.pro_legacy_quote_record(uuid,text) to authenticated,service_role;
notify pgrst,'reload schema';

$pro_install$; end if; end $pro_guard$;

-- ===== panel-queries-draft.sql =====
-- LOCAL ONLY. Relational scoped reads and atomic partial writes; workspace JSON is never consulted.
begin;
-- Preserve legacy timestamp spelling; safely index instants even for unscheduled empty dates.
create or replace function public.pro_instant(p_value text) returns timestamptz
language plpgsql immutable strict security invoker set search_path=public,pg_temp as $$
begin return p_value::timestamptz;exception when invalid_datetime_format or datetime_field_overflow then return null;end $$;
create index if not exists pro_work_overlap on public.pro_work(user_id,pro_instant("start"),pro_instant("end")) where not cancelled;
create index if not exists pro_availability_overlap on public.pro_availability(user_id,pro_instant("start"),pro_instant("end"));
-- Remove the historical overload so PostgREST can resolve optional mode/search unambiguously.
drop function if exists public.pro_agenda_page(uuid,text,text,jsonb);
create index if not exists pro_work_client_time on public.pro_work(user_id,pro_instant("start"),id);
create or replace function public.pro_agenda_page(p_user uuid,p_day text,p_month text,p_after jsonb default null,p_mode text default 'day',p_search text default '') returns jsonb
language sql security invoker set search_path=public,pg_temp as $$
 with bounds as (
 select p_day::date::timestamp at time zone 'America/Costa_Rica' as day_start,
 (p_day::date+1)::timestamp at time zone 'America/Costa_Rica' as day_end
 ), appointments as (
 select jsonb_strip_nulls(to_jsonb(r)-'user_id'-'position') as w,pro_instant(r.start) as at,r.id
 from pro_work r cross join bounds
 where r.user_id=p_user
 and (case when p_mode='upcoming' then not r.cancelled and r.stage<>'completed' and pro_instant(r."end")>now()
 else pro_instant(r.start)<day_end and pro_instant(r."end")>day_start end)
 and (p_mode<>'upcoming' or strpos(pro_catalog_search(r.client||' '||r.service),pro_catalog_search(p_search))>0)
 and (p_after is null or (pro_instant(r.start),r.id)>(pro_instant(p_after->>'start'),p_after->>'id'))
 order by pro_instant(r.start),r.id limit 21
 ), times as (
 select jsonb_build_object('start',s.start,'end',s."end") as s from pro_availability s cross join bounds
 where p_mode='day' and s.user_id=p_user and pro_instant(s.start)<day_end and pro_instant(s."end")>day_start
 ), days as (
 select day::date as day from generate_series((p_month||'-01')::date::timestamp,((p_month||'-01')::date+interval '1 month'-interval '1 day')::timestamp,interval '1 day') day
 ), marks as (
 select day::text as day from days where p_mode='day' and (
 exists(select 1 from pro_work w where w.user_id=p_user and not w.cancelled and pro_instant(w.start)<(days.day+1)::timestamp at time zone 'America/Costa_Rica' and pro_instant(w."end")>days.day::timestamp at time zone 'America/Costa_Rica')
 or exists(select 1 from pro_availability s where s.user_id=p_user and pro_instant(s.start)<(days.day+1)::timestamp at time zone 'America/Costa_Rica' and pro_instant(s."end")>days.day::timestamp at time zone 'America/Costa_Rica'))
 )
 select jsonb_build_object('revision',coalesce((select revision from pro_workspace_core where user_id=p_user),0),
 'work',coalesce((select jsonb_agg(w order by at,id) from (select * from appointments order by at,id limit 20) page),'[]'),
 'availability',coalesce((select jsonb_agg(s order by s->>'start') from times),'[]'),
 'marks',coalesce((select jsonb_agg(day order by day) from marks),'[]'),
 'nextCursor',case when (select count(*) from appointments)>20 then (select jsonb_build_object('start',to_char(at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'id',id) from appointments order by at,id offset 19 limit 1) else null end);
$$;
create or replace function public.pro_agenda_item(p_user uuid,p_id text) returns jsonb
language sql security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('revision',c.revision,'work',jsonb_strip_nulls(to_jsonb(w)-'user_id'-'position')) from pro_work w join pro_workspace_core c using(user_id) where w.user_id=p_user and w.id=p_id;
$$;
create or replace function public.pro_quotes_page(p_user uuid,p_search text default '',p_status text default 'all',p_client text default '',p_after jsonb default null) returns jsonb
language sql security invoker set search_path=public,pg_temp as $$
 with mine as (select id from professionals where profile_id=p_user),
 links as (select "quoteId" as quote_id,"clientId" as client_id from pro_quote_links where user_id=p_user),
 all_quotes as (
 select q.id::text as id,coalesce(q.title,'') as title,coalesce(q.client_name,'') as client,q.total,q.status,
 to_char(q.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"') as at,false as legacy,l.client_id as "clientId",'standard:'||q.id::text as key
 from quotes q left join links l on l.quote_id=q.id::text
 where q.deleted_at is null and (q.professional_id in (select id from mine) or q.client_id=p_user)
 union all
 select q.id,q.title,coalesce(c.name,''),
 (select coalesce(sum(net+floor(net*line.tax::double precision/100+0.5)),0)/100 from pro_legacy_quote_lines line cross join lateral (select floor(line.quantity::double precision*line.price::double precision*100+0.5) as net) cents where line.user_id=q.user_id and line.quote_id=q.id),
 q.status,'',true,q."clientId",'legacy:'||q.id
 from pro_legacy_quotes q left join pro_clients c on c.user_id=q.user_id and c.id=q."clientId" where q.user_id=p_user
 ), page as (
 select * from all_quotes where (p_status='all' or status=p_status) and (p_client='' or "clientId"=p_client)
 and strpos(pro_catalog_search(client||' '||title),pro_catalog_search(p_search))>0
 and (p_after is null or at<p_after->>'at' or at=p_after->>'at' and key>p_after->>'key')
 order by at desc,key limit 21
 )
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(r) order by at desc,key) from (select * from page order by at desc,key limit 20) r),'[]'),
 'nextCursor',case when (select count(*) from page)>20 then (select jsonb_build_object('at',at,'key',key) from page order by at desc,key offset 19 limit 1) else null end);
$$;

-- Global overlap checks execute under the owner lock, regardless of the visible page.
create or replace function public.pro_patch_core(p_user uuid,p_section text,p_row jsonb,p_revision integer) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v integer;previous jsonb;records integer;begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 select revision into v from pro_workspace_core where user_id=p_user for update;
 if coalesce(v,0)<>p_revision then raise exception 'revision conflict' using errcode='40001';end if;
 if p_section='work' then
 select jsonb_strip_nulls(to_jsonb(w)-'user_id'-'position') into previous from pro_work w where user_id=p_user and id=p_row->>'id';
 if previous is not null and previous->>'bookingClientId' is distinct from p_row->>'bookingClientId' then raise exception 'Booking identity is immutable' using errcode='22023';end if;
 if not exists(select 1 from pro_clients where user_id=p_user and id=p_row->>'clientId' and (not archived or previous->>'clientId'=id)) then raise exception 'Inactive client' using errcode='22023';end if;
 if coalesce(p_row->>'quoteId','')<>'' and not exists(select 1 from pro_legacy_quotes where user_id=p_user and id=p_row->>'quoteId' and "clientId"=p_row->>'clientId' and status='accepted') then raise exception 'Invalid legacy quote' using errcode='22023';end if;
 if p_row->>'externalQuoteId' is not null and not exists(select 1 from pro_quote_links l join quotes q on q.id::text=l."quoteId" join professionals p on p.id=q.professional_id where l.user_id=p_user and l."quoteId"=p_row->>'externalQuoteId' and l."clientId"=p_row->>'clientId' and p.profile_id=p_user and q.status='accepted' and q.deleted_at is null) then raise exception 'Invalid accepted quote' using errcode='22023';end if;
 if not (p_row->>'cancelled')::boolean and (p_row->>'stage'='scheduled' or p_row->>'start'<>'' or p_row->>'end'<>'') and (pro_instant(p_row->>'start') is null or pro_instant(p_row->>'end') is null or pro_instant(p_row->>'end')<=pro_instant(p_row->>'start')) then raise exception 'Invalid appointment time' using errcode='22023';end if;
 if not (p_row->>'cancelled')::boolean and p_row->>'stage'='scheduled' and exists(select 1 from pro_work where user_id=p_user and id<>p_row->>'id' and not cancelled and stage='scheduled' and pro_instant("start")<pro_instant(p_row->>'end') and pro_instant("end")>pro_instant(p_row->>'start')) then raise exception 'Overlapping appointment' using errcode='22023';end if;
 select count(*) into records from pro_work where user_id=p_user;
 elsif p_section='availability' then
 select jsonb_build_object('start',"start",'end',"end") into previous from pro_availability where user_id=p_user and "start"=p_row->>'start';
 if coalesce((p_row->>'remove')::boolean,false) then delete from pro_availability where user_id=p_user and "start"=p_row->>'start';
 elsif exists(select 1 from pro_availability where user_id=p_user and "start"<>p_row->>'start' and pro_instant("start")<pro_instant(p_row->>'end') and pro_instant("end")>pro_instant(p_row->>'start')) then raise exception 'Overlapping availability' using errcode='22023';end if;
 select count(*) into records from pro_availability where user_id=p_user;
 elsif p_section='quotes' then
 previous:=pro_legacy_quote_record(p_user,p_row->>'id');
 if previous is null or previous->>'status'<>'draft' and previous<>p_row then raise exception 'Resolved quote is immutable' using errcode='22023';end if;
 if not exists(select 1 from pro_clients where user_id=p_user and id=p_row->>'clientId' and not archived) then raise exception 'Inactive client' using errcode='22023';end if;
 select count(*) into records from pro_legacy_quotes where user_id=p_user;
 elsif p_section='quoteLinks' then
 select jsonb_build_object('quoteId',"quoteId",'clientId',"clientId") into previous from pro_quote_links where user_id=p_user and "quoteId"=p_row->>'quoteId';
 if previous is not null and previous<>p_row then raise exception 'Quote link is immutable' using errcode='22023';end if;
 if not exists(select 1 from quotes q join professionals p on p.id=q.professional_id join pro_clients c on c.user_id=p_user and c.id=p_row->>'clientId' and not c.archived where q.id::text=p_row->>'quoteId' and p.profile_id=p_user and q.deleted_at is null) then raise exception 'Invalid quote link' using errcode='22023';end if;
 select count(*) into records from pro_quote_links where user_id=p_user;
 else raise exception 'Invalid section' using errcode='22023';end if;
 if records+(case when previous is null then 1 else 0 end)>(case when p_section='availability' then 1000 else 10000 end) then raise exception 'Record limit' using errcode='22023';end if;
 v:=coalesce(v,0)+1;
 insert into pro_workspace_core(user_id,document,revision) values(p_user,'{"version":1,"social":[]}',v) on conflict(user_id) do update set revision=excluded.revision,updated_at=now();
 if not(p_section='availability' and coalesce((p_row->>'remove')::boolean,false)) then perform pro_upsert_panels(p_user,jsonb_build_object(p_section,jsonb_build_array(p_row)));end if;
 update pro_workspace_core set panel_fields=case when p_section=any(panel_fields) then panel_fields else array_append(panel_fields,p_section) end where user_id=p_user;
 return v;
end $$;
create or replace function public.pro_reserve_core(p_user uuid,p_client jsonb,p_work jsonb,p_revision integer) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v integer;begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 select revision into v from pro_workspace_core where user_id=p_user for update;
 if coalesce(v,0)<>p_revision then raise exception 'revision conflict' using errcode='40001';end if;
 if not exists(select 1 from pro_availability s where s.user_id=p_user and pro_instant(s.start)=pro_instant(p_work->>'start') and pro_instant(s."end")=pro_instant(p_work->>'end') and pro_instant(s.start)>now()+interval '15 minutes' and pro_instant(s.start)<now()+interval '90 days') or exists(select 1 from pro_work w where w.user_id=p_user and not w.cancelled and pro_instant(w.start)<pro_instant(p_work->>'end') and pro_instant(w."end")>pro_instant(p_work->>'start')) then raise exception 'Slot unavailable' using errcode='40001';end if;
 insert into pro_workspace_core(user_id,document,revision) values(p_user,'{"version":1,"social":[]}',coalesce(v,0)) on conflict do nothing;
 perform pro_upsert_catalog(p_user,jsonb_build_object('clients',jsonb_build_array(p_client)));
 return pro_patch_core(p_user,'work',p_work,p_revision);
end $$;
create or replace function public.pro_booking_context(p_user uuid,p_id text default '') returns jsonb
language sql security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('revision',coalesce((select revision from pro_workspace_core where user_id=p_user),0),
 'work',coalesce((select jsonb_agg(jsonb_strip_nulls(to_jsonb(w)-'user_id'-'position')) from pro_work w where user_id=p_user and id=p_id),'[]'),
 'availability',coalesce((select jsonb_agg(jsonb_build_object('start',s.start,'end',s."end") order by s.start) from pro_availability s where s.user_id=p_user and pro_instant(s.start)>now()+interval '15 minutes' and pro_instant(s.start)<now()+interval '90 days' and not exists(select 1 from pro_work w where w.user_id=p_user and not w.cancelled and pro_instant(w.start)<pro_instant(s."end") and pro_instant(w."end")>pro_instant(s.start))),'[]'));
$$;
-- Only the selected customer's history; no workspace reconstruction or N+1 requests.
create or replace function public.pro_client_history(p_user uuid,p_client text) returns jsonb
language sql security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object(
 'work',coalesce((select jsonb_agg(jsonb_strip_nulls(to_jsonb(w)-'user_id'-'position') order by position) from pro_work w where user_id=p_user and "clientId"=p_client),'[]'),
 'quotes',coalesce((select jsonb_agg(pro_legacy_quote_record(q.user_id,q.id) order by position) from pro_legacy_quotes q where user_id=p_user and "clientId"=p_client),'[]'),
 'quoteLinks',coalesce((select jsonb_agg(jsonb_build_object('quoteId',"quoteId",'clientId',"clientId") order by position) from pro_quote_links where user_id=p_user and "clientId"=p_client),'[]'));
$$;
revoke all on function public.pro_client_history(uuid,text) from public,anon,authenticated;
grant execute on function public.pro_client_history(uuid,text) to service_role;
revoke all on function public.pro_agenda_item(uuid,text),public.pro_agenda_page(uuid,text,text,jsonb,text,text),public.pro_quotes_page(uuid,text,text,text,jsonb),public.pro_patch_core(uuid,text,jsonb,integer),public.pro_reserve_core(uuid,jsonb,jsonb,integer),public.pro_booking_context(uuid,text) from public,anon,authenticated;
grant execute on function public.pro_agenda_item(uuid,text),public.pro_agenda_page(uuid,text,text,jsonb,text,text),public.pro_quotes_page(uuid,text,text,text,jsonb),public.pro_patch_core(uuid,text,jsonb,integer),public.pro_reserve_core(uuid,jsonb,jsonb,integer),public.pro_booking_context(uuid,text) to service_role;
notify pgrst,'reload schema';

-- Paged customer timeline. Only summaries cross the API; details retain their existing owner checks.
create or replace function public.pro_client_history_page(p_user uuid,p_client text,p_after jsonb default null) returns jsonb
language sql security invoker set search_path=public,pg_temp as $$
 with history as (
 select w.id,'work:'||w.id as key,'work'::text as kind,w.service as title,
 case when w.cancelled then 'cancelled' else w.stage end as status,
 coalesce(to_char(pro_instant(w.start) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'') as at,
 null::numeric as total,false as legacy,w.start as start,w."end" as "end"
 from pro_work w where w.user_id=p_user and w."clientId"=p_client
 union all
 select q.id::text,'standard:'||q.id::text,'quote',coalesce(q.title,''),q.status,
 to_char(q.created_at at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),q.total,false,null,null
 from pro_quote_links l join quotes q on q.id::text=l."quoteId"
 join professionals professional on professional.id=q.professional_id and professional.profile_id=p_user
 where l.user_id=p_user and l."clientId"=p_client and q.deleted_at is null
 union all
 select q.id,'legacy:'||q.id,'quote',q.title,q.status,'',
 (select coalesce(sum(net+floor(net*line.tax::double precision/100+0.5)),0)/100 from pro_legacy_quote_lines line cross join lateral (select floor(line.quantity::double precision*line.price::double precision*100+0.5) as net) cents where line.user_id=q.user_id and line.quote_id=q.id),true,null,null
 from pro_legacy_quotes q where q.user_id=p_user and q."clientId"=p_client
 ), page as (
 select * from history where p_after is null or at<p_after->>'at' or at=p_after->>'at' and key>p_after->>'key'
 order by at desc,key limit 21
 )
 select jsonb_build_object('items',coalesce((select jsonb_agg(to_jsonb(r) order by at desc,key) from (select * from page order by at desc,key limit 20) r),'[]'),
 'nextCursor',case when (select count(*) from page)>20 then (select jsonb_build_object('at',at,'key',key) from page order by at desc,key offset 19 limit 1) else null end);
$$;
revoke all on function public.pro_client_history_page(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function public.pro_client_history_page(uuid,text,jsonb) to service_role;

commit;

-- ===== appointment-requests-local.sql =====
-- LOCAL PRO ONLY. Additive requests, not a rewrite/backfill of existing bookings.
-- No notifications, emails, push outbox, charges or customer ledger mutations.
begin;
create table if not exists public.pro_appointment_requests(
 id uuid primary key,position bigint generated always as identity unique,
 professional_id uuid not null references public.professionals(id),
 owner_id uuid not null references public.profiles(id) on delete cascade,
 client_user_id uuid not null references public.profiles(id) on delete cascade,
 client_name text not null check(length(client_name) between 1 and 160),
 professional_name text not null check(length(professional_name) between 1 and 160),professional_slug text,
 service text not null check(length(service) between 1 and 160),duration_minutes integer not null check(duration_minutes between 15 and 480 and duration_minutes%15=0),
 location_kind text not null check(location_kind in ('agree','provider','customer','online')),
 location_text text not null default '' check(length(location_text)<=500),note text not null default '' check(length(note)<=500),
 requested_start timestamptz,preferred_day date,preference text not null default '' check(length(preference)<=200),
 proposed_start timestamptz,proposed_duration_minutes integer check(proposed_duration_minutes between 15 and 480 and proposed_duration_minutes%15=0),
 status text not null default 'requested' check(status in ('requested','proposed','confirmed','declined','cancelled','completed')),
 revision integer not null default 0 check(revision>=0),work_id text,
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 check(owner_id<>client_user_id),check(location_kind<>'customer' or length(btrim(location_text))>0),
 check((proposed_start is null)=(proposed_duration_minutes is null)),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id)
);
create index if not exists pro_appointment_owner_page on public.pro_appointment_requests(owner_id,position desc);
create index if not exists pro_appointment_client_page on public.pro_appointment_requests(client_user_id,position desc);
create index if not exists pro_appointment_client_created on public.pro_appointment_requests(client_user_id,created_at desc);
create unique index if not exists pro_appointment_work_once on public.pro_appointment_requests(owner_id,work_id) where work_id is not null;
-- Round 1 (2026-11-12): 'project_invite' rows link a customer account to an existing job via a
-- one-time invitation (work-client-invitations-local.sql). They are not appointments: lead lists,
-- the provider request list and the agenda lifecycle sync ignore them.
alter table public.pro_appointment_requests add column if not exists origin text not null default 'booking';
do $$begin if not exists(select 1 from pg_constraint where conname='pro_appointment_requests_origin_check') then alter table public.pro_appointment_requests add constraint pro_appointment_requests_origin_check check(origin in('booking','project_invite'));end if;end $$;
create table if not exists public.pro_appointment_events(
 position bigint generated always as identity primary key,request_id uuid not null references public.pro_appointment_requests(id) on delete cascade,
 actor_id uuid not null,side text not null check(side in ('provider','client')),action text not null,
 note text not null default '' check(length(note)<=500),start_at timestamptz,end_at timestamptz,
 status text not null check(status in ('requested','proposed','confirmed','declined','cancelled','completed')),at timestamptz not null default now()
);
create index if not exists pro_appointment_event_page on public.pro_appointment_events(request_id,position desc);
create table if not exists public.pro_appointment_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 request_id uuid not null references public.pro_appointment_requests(id) on delete cascade,input jsonb not null,result jsonb not null,
 primary key(actor_id,action_id)
);

create or replace function public.pro_appointment_time(p_value timestamptz) returns text
language sql stable security invoker set search_path=public,pg_temp as $$
 select case when p_value is null then null else to_char(p_value at time zone 'America/Costa_Rica','YYYY-MM-DD"T"HH24:MI:SS')||'-06:00' end;
$$;
create or replace function public.pro_appointment_enabled(p_owner uuid) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 -- Single Pro entitlement rule (pro_entitled, pro-entitled-draft.sql); public booking still needs a professionals row.
 select public.pro_entitled(p_owner) and exists(select 1 from public.professionals where profile_id=p_owner);
$$;
create or replace function public.pro_appointment_slot_free(p_owner uuid,p_start timestamptz,p_duration integer) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce(p_start>now()+interval '15 minutes' and p_start<now()+interval '90 days'
 and p_duration between 15 and 480 and p_duration%15=0
 and extract(second from p_start)=0 and extract(minute from p_start)::integer%15=0
 and exists(select 1 from pro_availability a where a.user_id=p_owner and pro_instant(a.start)<=p_start and pro_instant(a."end")>=p_start+make_interval(mins=>p_duration))
 and not exists(select 1 from pro_work w where w.user_id=p_owner and not w.cancelled and pro_instant(w.start)<p_start+make_interval(mins=>p_duration) and pro_instant(w."end")>p_start),false);
$$;
create or replace function public.pro_appointment_slots(p_owner uuid,p_day date,p_duration integer) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare first_at timestamptz;last_at timestamptz;result jsonb;
begin
 if p_day is null or p_day<(now() at time zone 'America/Costa_Rica')::date or p_day>(now() at time zone 'America/Costa_Rica')::date+90 or p_duration is null or p_duration<15 or p_duration>480 or p_duration%15<>0 then raise exception 'Invalid day or duration' using errcode='22023';end if;
 if not pro_appointment_enabled(p_owner) then return jsonb_build_object('slots','[]'::jsonb,'truncated',false);end if;
 first_at:=p_day::timestamp at time zone 'America/Costa_Rica';last_at:=(p_day+1)::timestamp at time zone 'America/Costa_Rica';
 select coalesce(jsonb_agg(jsonb_build_object('start',pro_appointment_time(t),'end',pro_appointment_time(t+make_interval(mins=>p_duration))) order by t),'[]') into result
 from generate_series(first_at,last_at-interval '15 minutes',interval '15 minutes') t where pro_appointment_slot_free(p_owner,t,p_duration);
 return jsonb_build_object('slots',result,'truncated',false);
end $$;
create or replace function public.pro_appointment_record(p_actor uuid,p_id uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',r.id,'position',r.position,'professionalId',r.professional_id,'professionalName',r.professional_name,'professionalSlug',coalesce(p.slug,r.professional_slug),
 'clientName',r.client_name,'service',r.service,'durationMinutes',r.duration_minutes,'locationKind',r.location_kind,'locationText',r.location_text,'note',r.note,
 'requestedStart',pro_appointment_time(r.requested_start),'preferredDay',r.preferred_day,'preference',r.preference,'proposedStart',pro_appointment_time(r.proposed_start),'proposedDurationMinutes',r.proposed_duration_minutes,
 'status',r.status,'revision',r.revision,'workId',r.work_id,
 'start',pro_appointment_time(case when r.work_id is not null then pro_instant(w.start) when r.status='proposed' then r.proposed_start else r.requested_start end),
 'end',pro_appointment_time(case when r.work_id is not null then pro_instant(w."end") when r.status='proposed' then r.proposed_start+make_interval(mins=>r.proposed_duration_minutes) else r.requested_start+make_interval(mins=>r.duration_minutes) end),
 'workStage',w.stage,'workCancelled',coalesce(w.cancelled,false),'origin',r.origin,'createdAt',r.created_at,'updatedAt',r.updated_at,'side',case when r.owner_id=p_actor then 'provider' else 'client' end)
 from pro_appointment_requests r left join professionals p on p.id=r.professional_id left join pro_work w on w.user_id=r.owner_id and w.id=r.work_id
 where r.id=p_id and p_actor in(r.owner_id,r.client_user_id) and exists(select 1 from profiles p where p.id=p_actor and not coalesce(p.is_disabled,false));
$$;
create or replace function public.pro_appointment_page(p_actor uuid,p_side text,p_after bigint default null,p_status text default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare result jsonb;next_key bigint;
begin
 if p_side not in ('provider','client') or p_side is null or p_after<1 or p_status is not null and p_status not in ('requested','proposed','confirmed','declined','cancelled','completed') then raise exception 'Invalid page' using errcode='22023';end if;
 if not exists(select 1 from profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 with page as(select id,position from pro_appointment_requests where (case when p_side='provider' then owner_id else client_user_id end)=p_actor and (p_side='client' or origin='booking') and (p_after is null or position<p_after) and (p_status is null or status=p_status) order by position desc limit 21)
 select coalesce((select jsonb_agg(pro_appointment_record(p_actor,id) order by position desc) from(select * from page order by position desc limit 20) x),'[]'),case when(select count(*) from page)>20 then(select position from page order by position desc offset 19 limit 1) else null end into result,next_key;
 return jsonb_build_object('items',result,'nextCursor',next_key);
end $$;
create or replace function public.pro_appointment_detail(p_actor uuid,p_id uuid,p_after bigint default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare result jsonb;events jsonb;next_key bigint;
begin
 if p_after<1 then raise exception 'Invalid cursor' using errcode='22023';end if;
 result:=pro_appointment_record(p_actor,p_id);if result is null then return null;end if;
 with page as(select * from pro_appointment_events where request_id=p_id and(p_after is null or position<p_after) order by position desc limit 21)
 select coalesce((select jsonb_agg(jsonb_build_object('position',position,'action',action,'side',side,'note',note,'start',pro_appointment_time(start_at),'end',pro_appointment_time(end_at),'status',status,'at',at) order by position desc) from(select * from page order by position desc limit 20) x),'[]'),case when(select count(*) from page)>20 then(select position from page order by position desc offset 19 limit 1) else null end into events,next_key;
 return jsonb_build_object('request',result,'events',events,'nextCursor',next_key);
end $$;

create or replace function public.pro_appointment_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;rid uuid;aid uuid;pid uuid;owner uuid;provider public.professionals;actor public.profiles;r public.pro_appointment_requests;prior public.pro_appointment_actions;
 keys text[];required text[];start_at timestamptz;duration integer;preferred date;current_rev integer;client_id text;client_name text;result jsonb;event_note text:='';event_side text;prior_flag text;
begin
 if p_actor is null or p_input is null or jsonb_typeof(p_input) is distinct from 'object' or not(p_input ?& array['action','id','actionId']) or jsonb_typeof(p_input->'action') is distinct from 'string' or jsonb_typeof(p_input->'id') is distinct from 'string' or jsonb_typeof(p_input->'actionId') is distinct from 'string' then raise exception 'Invalid operation' using errcode='22023';end if;
 act:=p_input->>'action';rid:=(p_input->>'id')::uuid;aid:=(p_input->>'actionId')::uuid;
 if act not in ('create','propose','confirm','accept','decline','cancel') then raise exception 'Invalid operation' using errcode='22023';end if;
 select * into actor from profiles where id=p_actor and not coalesce(is_disabled,false);if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if act='create' then
  -- A separate client namespace never collides with the agenda owner lock.
  -- Only CREATE takes it, before the owner lock, so daily quota checks serialize across providers.
  perform pg_advisory_xact_lock(hashtextextended('appointment-client:'||p_actor::text,0));
  if jsonb_typeof(p_input->'professionalId') is distinct from 'string' then raise exception 'Invalid provider' using errcode='22023';end if;
  pid:=(p_input->>'professionalId')::uuid;select * into provider from professionals where id=pid;if not found then raise exception 'Provider unavailable' using errcode='42501';end if;owner:=provider.profile_id;
 else select owner_id into owner from pro_appointment_requests where id=rid and p_actor in(owner_id,client_user_id);if not found then raise exception 'Request unavailable' using errcode='42501';end if;
 end if;
 perform pg_advisory_xact_lock(hashtextextended(owner::text,0));
 select * into prior from pro_appointment_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Idempotency key changed' using errcode='22023';end if;return prior.result;end if;
 if act not in ('cancel','decline') and not pro_appointment_enabled(owner) then raise exception 'Provider unavailable' using errcode='42501';end if;
 if act='create' then
  required:=array['action','id','actionId','professionalId','service','durationMinutes','locationKind','locationText','note','start','preferredDay','preference'];keys:=array(select jsonb_object_keys(p_input));
  if not(keys<@required and keys@>required) then raise exception 'Invalid request fields' using errcode='22023';end if;
  if owner=p_actor then raise exception 'Cannot request own service' using errcode='42501';end if;
  if exists(select 1 from pro_appointment_requests where id=rid) then raise exception 'Request ID already exists' using errcode='22023';end if;
  if jsonb_typeof(p_input->'service') is distinct from 'string' or length(btrim(p_input->>'service')) not between 1 and 160
   or jsonb_typeof(p_input->'durationMinutes') is distinct from 'number' or (p_input->>'durationMinutes')!~'^[0-9]{1,3}$'
   or jsonb_typeof(p_input->'locationKind') is distinct from 'string' or p_input->>'locationKind' not in ('agree','provider','customer','online')
   or jsonb_typeof(p_input->'locationText') is distinct from 'string' or length(p_input->>'locationText')>500
   or jsonb_typeof(p_input->'note') is distinct from 'string' or length(p_input->>'note')>500
   or jsonb_typeof(p_input->'preference') is distinct from 'string' or length(p_input->>'preference')>200
   or jsonb_typeof(p_input->'start') not in ('string','null') or jsonb_typeof(p_input->'preferredDay') not in ('string','null') then raise exception 'Invalid request values' using errcode='22023';end if;
  duration:=(p_input->>'durationMinutes')::integer;if duration<15 or duration>480 or duration%15<>0 then raise exception 'Invalid duration' using errcode='22023';end if;
  if p_input->>'locationKind'='customer' and btrim(p_input->>'locationText')='' then raise exception 'Location required' using errcode='22023';end if;
  if p_input->>'preferredDay' is not null then
   if (p_input->>'preferredDay')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' then raise exception 'Invalid preferred date' using errcode='22023';end if;
   begin preferred:=(p_input->>'preferredDay')::date;exception when invalid_datetime_format or datetime_field_overflow then raise exception 'Invalid preferred date' using errcode='22023';end;
   if preferred<(now() at time zone 'America/Costa_Rica')::date or preferred>(now() at time zone 'America/Costa_Rica')::date+90 then raise exception 'Invalid preferred date' using errcode='22023';end if;
  end if;
  if p_input->>'start' is not null then start_at:=pro_instant(p_input->>'start');if not pro_appointment_slot_free(owner,start_at,duration) then raise exception 'Slot unavailable' using errcode='40001';end if;end if;
  if (select count(*) from pro_appointment_requests where client_user_id=p_actor and owner_id=owner and status in ('requested','proposed','confirmed'))>=20 or (select count(*) from pro_appointment_requests where client_user_id=p_actor and created_at>=date_trunc('day',now() at time zone 'America/Costa_Rica') at time zone 'America/Costa_Rica')>=100 then raise exception 'Request limit reached' using errcode='54000';end if;
  client_name:=left(coalesce(nullif(btrim(actor.full_name),''),'Cliente'),160);
  insert into pro_appointment_requests(id,professional_id,owner_id,client_user_id,client_name,professional_name,professional_slug,service,duration_minutes,location_kind,location_text,note,requested_start,preferred_day,preference)
  values(rid,pid,owner,p_actor,client_name,left(coalesce(nullif(btrim(provider.business_name),''),'Profesional'),160),provider.slug,btrim(p_input->>'service'),duration,p_input->>'locationKind',btrim(p_input->>'locationText'),btrim(p_input->>'note'),start_at,preferred,btrim(p_input->>'preference')) returning * into r;
  event_side:='client';event_note:=r.note;
 else
  select * into r from pro_appointment_requests where id=rid for update;
  required:=case when act='propose' then array['action','id','actionId','revision','start','durationMinutes','note'] when act in ('cancel','decline') then array['action','id','actionId','revision','note'] else array['action','id','actionId','revision'] end;
  keys:=array(select jsonb_object_keys(p_input));
  if not(keys<@required and keys@>required) or jsonb_typeof(p_input->'revision') is distinct from 'number' or (p_input->>'revision')!~'^[0-9]{1,9}$' then raise exception 'Invalid action fields' using errcode='22023';end if;
  if r.revision<>(p_input->>'revision')::integer then raise exception 'Request changed' using errcode='40001';end if;
  if act in ('propose','confirm','decline') and p_actor<>owner or act='accept' and p_actor<>r.client_user_id then raise exception 'Forbidden action' using errcode='42501';end if;
  if act in ('propose','confirm','decline') and r.status not in ('requested','proposed') or act='accept' and r.status<>'proposed' or act='cancel' and r.status not in ('requested','proposed','confirmed') then raise exception 'Invalid request state' using errcode='40001';end if;
  event_side:=case when p_actor=owner then 'provider' else 'client' end;
  if act in ('propose','decline','cancel') then
   if jsonb_typeof(p_input->'note') is distinct from 'string' or length(p_input->>'note')>500 then raise exception 'Invalid note' using errcode='22023';end if;event_note:=btrim(p_input->>'note');
  end if;
  if act='propose' then
   if jsonb_typeof(p_input->'start') is distinct from 'string' or jsonb_typeof(p_input->'durationMinutes') is distinct from 'number' or (p_input->>'durationMinutes')!~'^[0-9]{1,3}$' then raise exception 'Invalid proposal' using errcode='22023';end if;
   start_at:=pro_instant(p_input->>'start');duration:=(p_input->>'durationMinutes')::integer;
   if not pro_appointment_slot_free(owner,start_at,duration) then raise exception 'Slot unavailable' using errcode='40001';end if;
   r.proposed_start:=start_at;r.proposed_duration_minutes:=duration;r.status:='proposed';
  elsif act in ('confirm','accept') then
   if act='confirm' and r.status<>'requested' then raise exception 'Client must accept proposal' using errcode='40001';end if;
   start_at:=case when act='confirm' then r.requested_start else r.proposed_start end;duration:=case when act='confirm' then r.duration_minutes else r.proposed_duration_minutes end;
   if not pro_appointment_slot_free(owner,start_at,duration) then raise exception 'Slot unavailable' using errcode='40001';end if;
   if (select count(*) from pro_work where user_id=owner)>=10000 then raise exception 'Work limit reached' using errcode='54000';end if;
   select revision into current_rev from pro_workspace_core where user_id=owner for update;
   insert into pro_workspace_core(user_id,document,revision) values(owner,'{"version":1,"social":[]}',coalesce(current_rev,0)) on conflict do nothing;
   client_id:='reservation-'||r.client_user_id::text;
   -- Only create a missing contact; never overwrite saved fiscal/contact details.
   insert into pro_clients(user_id,id,name,email,phone,notes,archived) values(owner,client_id,r.client_name,'','','',false) on conflict(user_id,id) do nothing;
   if exists(select 1 from pro_clients where user_id=owner and id=client_id and archived) then update pro_clients set archived=false where user_id=owner and id=client_id;end if;
   insert into pro_work(user_id,id,client,service,stage,start,"end","clientId",cancelled,"bookingClientId")
   select owner,r.id::text,c.name,r.service,'scheduled',pro_appointment_time(start_at),pro_appointment_time(start_at+make_interval(mins=>duration)),client_id,false,r.client_user_id::text from pro_clients c where c.user_id=owner and c.id=client_id;
   update pro_workspace_core set revision=revision+1,updated_at=now(),panel_fields=case when 'work'=any(panel_fields) then panel_fields else array_append(panel_fields,'work') end where user_id=owner;
   r.work_id:=r.id::text;r.status:='confirmed';
  elsif act='decline' then r.status:='declined';
  elsif act='cancel' then
   if r.work_id is not null then
    if not exists(select 1 from pro_work w where w.user_id=owner and w.id=r.work_id and not w.cancelled and w.stage<>'completed' and w."bookingClientId"=r.client_user_id::text and pro_instant(w.start)>now()) then raise exception 'Appointment already changed or started' using errcode='40001';end if;
    prior_flag:=current_setting('contratacr.appointment_request',true);perform set_config('contratacr.appointment_request',r.id::text,true);
    update pro_work set cancelled=true where user_id=owner and id=r.work_id;
    perform set_config('contratacr.appointment_request',coalesce(prior_flag,''),true);
    update pro_workspace_core set revision=revision+1,updated_at=now() where user_id=owner;
   end if;r.status:='cancelled';
  end if;
  r.revision:=r.revision+1;
  update pro_appointment_requests set proposed_start=r.proposed_start,proposed_duration_minutes=r.proposed_duration_minutes,status=r.status,revision=r.revision,work_id=r.work_id,updated_at=now() where id=r.id returning * into r;
 end if;
 if r.work_id is not null then select pro_instant(w.start),extract(epoch from(pro_instant(w."end")-pro_instant(w.start)))::integer/60 into start_at,duration from pro_work w where w.user_id=owner and w.id=r.work_id;
 elsif r.status='proposed' then start_at:=r.proposed_start;duration:=r.proposed_duration_minutes;
 else start_at:=r.requested_start;duration:=r.duration_minutes;end if;
 insert into pro_appointment_events(request_id,actor_id,side,action,note,start_at,end_at,status) values(r.id,p_actor,event_side,act,event_note,start_at,start_at+make_interval(mins=>duration),r.status);
 result:=jsonb_build_object('id',r.id,'revision',r.revision,'status',r.status,'workId',r.work_id);
 insert into pro_appointment_actions(actor_id,action_id,request_id,input,result) values(p_actor,aid,r.id,p_input,result);
 return result;
end $$;

-- Only linked NEW requests are governed. All legacy jobs retain their old behavior.
create or replace function public.pro_appointment_sync_work() returns trigger
language plpgsql security definer set search_path=public,pg_temp as $$
declare r public.pro_appointment_requests;new_status text;event_action text;
begin
 if not exists(select 1 from pro_appointment_requests where owner_id=new.user_id and work_id=new.id) then return new;end if;
 perform pg_advisory_xact_lock(hashtextextended(new.user_id::text,0));
 select * into r from pro_appointment_requests where owner_id=new.user_id and work_id=new.id for update;
 if r.origin='project_invite' then
  if new."clientId" is distinct from old."clientId" and r.status in('confirmed','completed') then raise exception 'Unlink the customer account first' using errcode='23514',hint='pro_invite_client_change';end if;
  return new;
 end if;
 if current_setting('contratacr.appointment_request',true)=r.id::text then return new;end if;
 if new.start is distinct from old.start or new."end" is distinct from old."end" or new.service is distinct from old.service or new."clientId" is distinct from old."clientId" or new."bookingClientId" is distinct from old."bookingClientId" then raise exception 'Use the appointment agreement workflow' using errcode='23514';end if;
 if new.cancelled is not distinct from old.cancelled and new.stage is not distinct from old.stage then return new;end if;
 if r.status in ('cancelled','completed') or (not new.cancelled and new.stage not in ('scheduled','completed')) then raise exception 'Appointment state cannot be reopened' using errcode='23514';end if;
 if new.cancelled and pro_instant(new.start)<=now() then raise exception 'Appointment already started' using errcode='23514';end if;
 new_status:=case when new.cancelled then 'cancelled' when new.stage='completed' then 'completed' else 'confirmed' end;event_action:=case when new.cancelled then 'cancel' when new.stage='completed' then 'complete' else 'agenda_updated' end;
 update pro_appointment_requests set status=new_status,revision=revision+1,updated_at=now() where id=r.id;
 insert into pro_appointment_events(request_id,actor_id,side,action,start_at,end_at,status) values(r.id,r.owner_id,'provider',event_action,pro_instant(new.start),pro_instant(new."end"),new_status);
 return new;
end $$;
revoke all on function public.pro_appointment_sync_work() from public,anon,authenticated;
drop trigger if exists pro_appointment_sync_work on public.pro_work;
create trigger pro_appointment_sync_work before update on public.pro_work for each row execute function public.pro_appointment_sync_work();

alter table public.pro_appointment_requests enable row level security;
alter table public.pro_appointment_events enable row level security;
alter table public.pro_appointment_actions enable row level security;
revoke all on public.pro_appointment_requests,public.pro_appointment_events,public.pro_appointment_actions from public,anon,authenticated;
grant select,insert,update,delete on public.pro_appointment_requests,public.pro_appointment_events,public.pro_appointment_actions to service_role;
grant usage,select on sequence public.pro_appointment_requests_position_seq,public.pro_appointment_events_position_seq to service_role;
revoke all on function public.pro_appointment_time(timestamptz),public.pro_appointment_enabled(uuid),public.pro_appointment_slot_free(uuid,timestamptz,integer),public.pro_appointment_slots(uuid,date,integer),public.pro_appointment_record(uuid,uuid),public.pro_appointment_page(uuid,text,bigint,text),public.pro_appointment_detail(uuid,uuid,bigint),public.pro_appointment_mutate(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_appointment_time(timestamptz),public.pro_appointment_enabled(uuid),public.pro_appointment_slot_free(uuid,timestamptz,integer),public.pro_appointment_slots(uuid,date,integer),public.pro_appointment_record(uuid,uuid),public.pro_appointment_page(uuid,text,bigint,text),public.pro_appointment_detail(uuid,uuid,bigint),public.pro_appointment_mutate(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== client-operations-draft.sql =====
-- LOCAL ONLY. Additive storage: no backfill, inferred debt, or workspace JSON changes.
begin;
create table if not exists public.pro_client_entries(
 user_id uuid not null,
 id uuid not null,
 position bigint generated always as identity,
 client_id text not null,
 work_id text not null,
 kind text not null check(kind in ('agreement','payment','material','payment_void','material_return')),
 amount_cents bigint check(amount_cents between 0 and 10000000000),
 product_id text,
 quantity numeric(14,3) check(quantity>0 and quantity<=100000),
 unit_cost numeric,
 label text not null check(length(label)<=160),
 reversal_id uuid,
 request_hash text not null,
 created_at timestamptz not null default now(),
 primary key(user_id,id),
 foreign key(user_id,work_id) references public.pro_work(user_id,id),
 foreign key(user_id,client_id) references public.pro_clients(user_id,id),
 foreign key(user_id,product_id) references public.pro_products(user_id,id),
 foreign key(user_id,reversal_id) references public.pro_client_entries(user_id,id),
 check((kind in ('agreement','payment','payment_void') and amount_cents is not null and product_id is null and quantity is null and unit_cost is null)
 or (kind in ('material','material_return') and amount_cents is null and product_id is not null and quantity is not null and unit_cost is not null)),
 check((kind in ('payment_void','material_return'))=(reversal_id is not null))
);
do $$ begin
 if not exists(select 1 from pg_constraint where conrelid='public.pro_client_entries'::regclass and conname='pro_client_entries_owner_fkey') then
  alter table public.pro_client_entries add constraint pro_client_entries_owner_fkey foreign key(user_id) references public.profiles(id) on delete cascade;
 end if;
end $$;
create unique index if not exists pro_client_entry_reversal on public.pro_client_entries(user_id,reversal_id) where reversal_id is not null;
create index if not exists pro_client_entries_work on public.pro_client_entries(user_id,work_id,position desc);
create index if not exists pro_client_entries_customer on public.pro_client_entries(user_id,client_id,position desc);
alter table public.pro_client_entries enable row level security;
drop policy if exists pro_client_entries_owner on public.pro_client_entries;
create policy pro_client_entries_owner on public.pro_client_entries for select to authenticated using(user_id=auth.uid());
revoke all on public.pro_client_entries from public,anon,authenticated;
grant select on public.pro_client_entries to authenticated;
grant all on public.pro_client_entries to service_role;
grant usage,select on sequence public.pro_client_entries_position_seq to service_role;
create or replace function public.pro_work_account(p_user uuid,p_work text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with account_values as (
 select w.*,
 (select amount_cents from pro_client_entries where user_id=p_user and work_id=w.id and kind='agreement' order by position desc limit 1) as agreed,
 (select coalesce(sum(case when kind='payment' then amount_cents when kind='payment_void' then -amount_cents else 0 end),0) from pro_client_entries where user_id=p_user and work_id=w.id) as paid,
 (select count(*) from pro_client_entries e where e.user_id=p_user and e.work_id=w.id and e.kind='material' and not exists(select 1 from pro_client_entries r where r.user_id=e.user_id and r.reversal_id=e.id)) as materials,
 (select coalesce(sum(case when kind='material' then round(quantity*unit_cost,2) when kind='material_return' then -round(quantity*unit_cost,2) else 0 end),0) from pro_client_entries where user_id=p_user and work_id=w.id) as material_cost
 from pro_work w where w.user_id=p_user and w.id=p_work
 ) select jsonb_build_object('id',id,'service',service,'stage',stage,'cancelled',cancelled,'start',start,'quoteId',"quoteId",'externalQuoteId',"externalQuoteId",'agreedCents',agreed,'paidCents',paid,'balanceCents',coalesce(agreed,0)-paid,'materialCount',materials,'materialCost',material_cost) from account_values;
$$;
create or replace function public.pro_client_operations_page(p_user uuid,p_client text,p_work text default '',p_after jsonb default null,p_entries_after jsonb default null) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with accounts as materialized (
 select pro_work_account(p_user,w.id) as a,coalesce(to_char(pro_instant(w.start) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'') as at from pro_work w where w.user_id=p_user and w."clientId"=p_client
 ), page as (
 select a,at from accounts where p_after is null or at<p_after->>'at' or at=p_after->>'at' and a->>'id'>p_after->>'id' order by at desc,a->>'id' limit 21
 ), entries as (
 select e.*,exists(select 1 from pro_client_entries r where r.user_id=e.user_id and r.reversal_id=e.id) as reversed
 from pro_client_entries e where e.user_id=p_user and e.client_id=p_client and e.work_id=p_work and (p_entries_after is null or e.position<(p_entries_after->>'position')::bigint) order by e.position desc limit 21
 ) select jsonb_build_object(
 'revision',(select revision from pro_workspace_core where user_id=p_user),
 'summary',jsonb_build_object('agreedCents',coalesce((select sum((a->>'agreedCents')::bigint) from accounts),0),'paidCents',coalesce((select sum((a->>'paidCents')::bigint) from accounts),0),'balanceCents',coalesce((select sum((a->>'balanceCents')::bigint) from accounts),0),'unpriced',(select count(*) from accounts where a->>'agreedCents' is null and not(a->>'cancelled')::boolean)),
 'items',coalesce((select jsonb_agg(a order by at desc,a->>'id') from (select a,at from page order by at desc,a->>'id' limit 20) p),'[]'),
 'nextCursor',case when (select count(*) from page)>20 then (select jsonb_build_object('at',at,'id',a->>'id') from page order by at desc,a->>'id' offset 19 limit 1) else null end,
 'work',(select a from accounts where a->>'id'=p_work),
 'entries',coalesce((select jsonb_agg(jsonb_build_object('id',id,'kind',kind,'amountCents',amount_cents,'quantity',quantity,'label',label,'at',created_at,'reversed',reversed) order by position desc) from (select * from entries order by position desc limit 20) p),'[]'),
 'nextEntryCursor',case when (select count(*) from entries)>20 then (select jsonb_build_object('position',position::text) from entries order by position desc offset 19 limit 1) else null end
 ) where exists(select 1 from pro_clients where user_id=p_user and id=p_client) and (p_work='' or exists(select 1 from pro_work where user_id=p_user and "clientId"=p_client and id=p_work));
$$;
create or replace function public.pro_record_client_operation(p_user uuid,p_input jsonb,p_revision integer) returns integer
language plpgsql security invoker set search_path=public,pg_temp as $$
declare v integer; w pro_work; c pro_clients; product pro_products; original pro_client_entries; previous pro_client_entries;
 account jsonb; k text:=p_input->>'kind'; n bigint; qty numeric; title text; prod text; cost numeric; reverse_id uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 select revision into v from pro_workspace_core where user_id=p_user for update;
 select * into previous from pro_client_entries where user_id=p_user and id=(p_input->>'actionId')::uuid;
 if found then
  if previous.request_hash<>md5(p_input::text) then raise exception 'Request changed' using errcode='22023';end if;
  return v;
 end if;
 if v is null or v<>p_revision then raise exception 'Revision changed' using errcode='40001';end if;
 select * into w from pro_work where user_id=p_user and id=p_input->>'workId' for update;
 select * into c from pro_clients where user_id=p_user and id=p_input->>'clientId';
 if w.id is null or c.id is null or w."clientId"<>c.id then raise exception 'Invalid relationship' using errcode='22023';end if;
 if k not in ('payment_void','material_return') and (w.cancelled or c.archived) then raise exception 'Inactive work/customer' using errcode='22023';end if;
 account:=pro_work_account(p_user,w.id);
 if k in ('agreement','payment') then
  n:=(p_input->>'amountCents')::bigint;
  if n is null or n<0 or n>10000000000 or (p_input->>'amountCents')::numeric<>n then raise exception 'Invalid amount' using errcode='22023';end if;
  if k='agreement' and n<(account->>'paidCents')::bigint then raise exception 'Below paid amount' using errcode='22023';end if;
  if k='payment' and (n=0 or account->>'agreedCents' is null or n>(account->>'balanceCents')::bigint) then raise exception 'Invalid payment' using errcode='22023';end if;
  title:=coalesce(p_input->>'note','');
 elsif k='material' then
  qty:=(p_input->>'quantity')::numeric;
  select * into product from pro_products where user_id=p_user and id=p_input->>'productId' for update;
  if product.id is null or product.archived or product."itemType"='service' or qty is null or qty<=0 or qty>100000 or qty<>round(qty,3) or product.stock<qty then raise exception 'Invalid stock' using errcode='22023';end if;
  prod:=product.id;cost:=product.cost;title:=product.name;
 elsif k in ('payment_void','material_return') then
  select * into original from pro_client_entries where user_id=p_user and id=(p_input->>'entryId')::uuid;
  if original.id is null or original.work_id<>w.id or original.client_id<>c.id or original.kind<>(case when k='payment_void' then 'payment' else 'material' end) or exists(select 1 from pro_client_entries where user_id=p_user and reversal_id=original.id) or nullif(trim(p_input->>'note'),'') is null then raise exception 'Invalid reversal' using errcode='22023';end if;
  reverse_id:=original.id;title:=p_input->>'note';n:=original.amount_cents;qty:=original.quantity;prod:=original.product_id;cost:=original.unit_cost;
 else raise exception 'Invalid operation' using errcode='22023';end if;
 insert into pro_client_entries(user_id,id,client_id,work_id,kind,amount_cents,product_id,quantity,unit_cost,label,reversal_id,request_hash)
 values(p_user,(p_input->>'actionId')::uuid,c.id,w.id,k,n,prod,qty,cost,title,reverse_id,md5(p_input::text));
 if k in ('material','material_return') then
  update pro_products set stock=round(stock+(case when k='material' then -qty else qty end),3) where user_id=p_user and id=prod;
  insert into pro_movements(user_id,id,"productId",delta,reason,at) values(p_user,'client-operation:'||(p_input->>'actionId'),prod,case when k='material' then -qty else qty end,left((case when k='material' then 'Material utilizado: ' else 'Devolución: ' end)||w.service,160),to_char(now() at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'));
 end if;
 update pro_workspace_core set revision=revision+1,updated_at=now() where user_id=p_user returning revision into v;
 return v;
end $$;
-- Protect operational history from reassignments through both scoped and compatibility writers.
create or replace function public.pro_protect_work_account() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if (old."clientId"<>new."clientId" or old."quoteId" is distinct from new."quoteId" or old."externalQuoteId" is distinct from new."externalQuoteId") and exists(select 1 from pro_client_entries where user_id=old.user_id and work_id=old.id) then raise exception 'Work with entries cannot be reassigned' using errcode='22023';end if;
 return new;
end $$;
drop trigger if exists pro_protect_work_account on public.pro_work;
create trigger pro_protect_work_account before update on public.pro_work for each row execute function public.pro_protect_work_account();
revoke all on function public.pro_work_account(uuid,text),public.pro_client_operations_page(uuid,text,text,jsonb,jsonb),public.pro_record_client_operation(uuid,jsonb,integer),public.pro_protect_work_account() from public,anon,authenticated;
grant execute on function public.pro_work_account(uuid,text),public.pro_client_operations_page(uuid,text,text,jsonb,jsonb),public.pro_record_client_operation(uuid,jsonb,integer),public.pro_protect_work_account() to service_role;
notify pgrst,'reload schema';
commit;

-- ===== invoice-drafts-local.sql =====
-- LOCAL ONLY. Additive draft storage. No fiscal identifiers, emission, payments or stock writes.
begin;
create table if not exists public.pro_invoice_drafts(
 user_id uuid not null references public.profiles(id) on delete cascade,
 id uuid not null,
 client_id text not null,
 source_kind text not null check(source_kind in ('work','quote','legacy_quote')),
 source_id text not null,
 work_id text,
 quote_origin_key text,
 title text not null check(length(title) between 1 and 160),
 notes text not null default '' check(length(notes)<=2000),
 receiver_name text not null check(length(receiver_name) between 1 and 160),
 receiver_identification text not null,receiver_email text not null,receiver_phone text not null,receiver_address text not null,
 total_cents bigint not null check(total_cents between 0 and 10000000000),
 tax_cents bigint,
 agreed_cents bigint,paid_cents bigint,balance_cents bigint,
 material_count integer not null,material_cost numeric not null,
 basis text not null check(basis in ('agreement','quote','manual')),
 source_fingerprint text not null,
 revision integer not null default 1 check(revision>0),
 status text not null default 'draft' check(status='draft'),
 currency text not null default 'CRC' check(currency='CRC'),
 created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(user_id,id),unique(user_id,source_kind,source_id),
 foreign key(user_id,client_id) references public.pro_clients(user_id,id),
 foreign key(user_id,work_id) references public.pro_work(user_id,id)
);
create unique index if not exists pro_invoice_draft_quote_origin on public.pro_invoice_drafts(user_id,quote_origin_key) where quote_origin_key is not null;
create index if not exists pro_invoice_draft_client on public.pro_invoice_drafts(user_id,client_id,created_at desc,id);
create table if not exists public.pro_invoice_lines(
 user_id uuid not null,draft_id uuid not null,line_number integer not null check(line_number between 1 and 100),
 description text not null,quantity numeric not null check(quantity>0),unit_amount numeric not null check(unit_amount>=0),tax_rate numeric,
 primary key(user_id,draft_id,line_number),foreign key(user_id,draft_id) references public.pro_invoice_drafts(user_id,id) on delete cascade
);
create table if not exists public.pro_invoice_materials(
 user_id uuid not null,draft_id uuid not null,entry_id uuid not null,product_id text not null,
 name text not null,quantity numeric not null check(quantity>0),unit_cost numeric not null,
 primary key(user_id,draft_id,entry_id),foreign key(user_id,draft_id) references public.pro_invoice_drafts(user_id,id) on delete cascade
);
alter table pro_invoice_drafts enable row level security;
alter table pro_invoice_lines enable row level security;
alter table pro_invoice_materials enable row level security;
drop policy if exists pro_invoice_drafts_owner on pro_invoice_drafts;
drop policy if exists pro_invoice_lines_owner on pro_invoice_lines;
drop policy if exists pro_invoice_materials_owner on pro_invoice_materials;
create policy pro_invoice_drafts_owner on pro_invoice_drafts for select to authenticated using(user_id=auth.uid());
create policy pro_invoice_lines_owner on pro_invoice_lines for select to authenticated using(user_id=auth.uid());
create policy pro_invoice_materials_owner on pro_invoice_materials for select to authenticated using(user_id=auth.uid());
revoke all on pro_invoice_drafts,pro_invoice_lines,pro_invoice_materials from public,anon,authenticated;
grant select on pro_invoice_drafts,pro_invoice_lines,pro_invoice_materials to authenticated;
grant all on pro_invoice_drafts,pro_invoice_lines,pro_invoice_materials to service_role;

create or replace function public.pro_invoice_source(p_user uuid,p_kind text,p_id text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w pro_work;c pro_clients;q jsonb;v jsonb;account jsonb;receiver jsonb;lines jsonb:='[]';
 client_id text;v_quote_id text;quote_kind text;v_work_id text;related integer:=0;related_id text;
 source_title text;total bigint;tax bigint;quote_total bigint;materials integer:=0;material_cost numeric:=0;material_digest text:='';quote_origin text;basis text;existing uuid;
begin
 if p_kind='work' then
  select * into w from pro_work where user_id=p_user and id=p_id;
  if w.id is null or w.cancelled then return null;end if;
  client_id:=w."clientId";v_work_id:=w.id;source_title:=w.service;
  if w."externalQuoteId" is not null then v_quote_id:=w."externalQuoteId";quote_kind:='quote';
  elsif w."quoteId" is not null then v_quote_id:=w."quoteId";quote_kind:='legacy_quote';end if;
 elsif p_kind in ('quote','legacy_quote') then v_quote_id:=p_id;quote_kind:=p_kind;
 else return null;end if;
 if quote_kind='quote' then
  select to_jsonb(r) into q from quotes r join professionals p on p.id=r.professional_id and p.profile_id=p_user where r.id::text=v_quote_id and r.deleted_at is null and r.status in ('draft','sent','accepted');
  if q is not null then
   select "clientId" into related_id from pro_quote_links where user_id=p_user and "quoteId"=v_quote_id;
   if p_kind='work' and related_id is distinct from client_id then q:=null;
   else
    client_id:=coalesce(client_id,related_id);
    select coalesce(jsonb_agg(jsonb_build_object('description',r->>'description','quantity',(r->>'quantity')::numeric,'unitAmount',(r->>'unit_price')::numeric,'taxRate',null) order by n),'[]') into lines from jsonb_array_elements(q->'items') with ordinality e(r,n);
    quote_total:=round((q->>'total')::numeric*100);tax:=round((q->>'tax_amount')::numeric*100);
   end if;
  end if;
 elsif quote_kind='legacy_quote' then
  q:=pro_legacy_quote_record(p_user,v_quote_id);
  if q is not null and (q->>'status'='declined' or p_kind='work' and q->>'clientId'<>client_id) then q:=null;end if;
  if q is not null then
   client_id:=coalesce(client_id,q->>'clientId');
   select coalesce(jsonb_agg(jsonb_build_object('description',l.description,'quantity',l.quantity,'unitAmount',l.price,'taxRate',l.tax) order by l.line_number),'[]'),
    coalesce(sum(net+floor(net*l.tax::double precision/100+0.5)),0),coalesce(sum(floor(net*l.tax::double precision/100+0.5)),0)
    into lines,quote_total,tax from pro_legacy_quote_lines l cross join lateral (select floor(l.quantity::double precision*l.price::double precision*100+0.5) as net) cents where l.user_id=p_user and l.quote_id=v_quote_id;
  end if;
 end if;
 if p_kind<>'work' then
  if q is null then return null;end if;
  select count(*),min(id) into related,related_id from pro_work where user_id=p_user and not cancelled and (case when quote_kind='quote' then "externalQuoteId"=v_quote_id else "quoteId"=v_quote_id end);
  if related=1 and client_id is not null then return pro_invoice_source(p_user,'work',related_id);end if;
  source_title:=coalesce(nullif(q->>'title',''),'Cotización');
 end if;
 if client_id is not null then
  select * into c from pro_clients where user_id=p_user and id=client_id;
  if c.id is null or c.archived then return null;end if;
  receiver:=jsonb_build_object('name',c.name,'identification',coalesce(c.identification,''),'email',c.email,'phone',c.phone,'address',coalesce(c.address,''));
 else
  receiver:=jsonb_build_object('name',coalesce(q->>'client_name',''),'identification',coalesce(q->>'client_cedula',''),'email',coalesce(q->>'client_email',''),'phone',coalesce(q->>'client_phone',''),'address','');
 end if;
 if v_work_id is not null then
  if q is not null then
   select count(*) into related from pro_work where user_id=p_user and not cancelled and (case when quote_kind='quote' then "externalQuoteId"=v_quote_id else "quoteId"=v_quote_id end);
  end if;
  -- A shared quote is not a per-work allocation. Require an individual agreement
  -- or an explicit manual amount; never duplicate the whole quote automatically.
  if related>1 then quote_total:=null;lines:='[]';tax:=null;end if;
  account:=pro_work_account(p_user,v_work_id);
  if account->>'agreedCents' is not null then
   total:=(account->>'agreedCents')::bigint;basis:='agreement';
   if quote_total is distinct from total then
    lines:=jsonb_build_array(jsonb_build_object('description',source_title,'quantity',1,'unitAmount',total::numeric/100,'taxRate',null));tax:=null;
   end if;
  elsif quote_total is not null then total:=quote_total;basis:='quote';
  else basis:='manual';end if;
  select count(*),coalesce(sum(round(quantity*unit_cost,2)),0),coalesce(md5(string_agg(id::text||':'||quantity::text||':'||unit_cost::text||':'||label,'|' order by id)),'') into materials,material_cost,material_digest
   from pro_client_entries e where e.user_id=p_user and e.work_id=v_work_id and e.kind='material' and not exists(select 1 from pro_client_entries r where r.user_id=e.user_id and r.reversal_id=e.id);
  if q is not null then
   select count(*) into related from pro_work where user_id=p_user and not cancelled and (case when quote_kind='quote' then "externalQuoteId"=v_quote_id else "quoteId"=v_quote_id end);
  end if;
 else total:=quote_total;basis:='quote';end if;
 if q is not null and (v_work_id is null or related=1) then quote_origin:=quote_kind||':'||v_quote_id;end if;
 v:=jsonb_build_object('kind',p_kind,'sourceId',p_id,'workId',v_work_id,'quoteId',case when q is not null then v_quote_id else null end,'quoteKind',case when q is not null then quote_kind else null end,'quoteOriginKey',quote_origin,'clientId',client_id,'receiver',receiver,'title',source_title,'lines',lines,'totalCents',total,'taxCents',tax,'agreedCents',account->'agreedCents','paidCents',account->'paidCents','balanceCents',case when account->>'agreedCents' is not null then account->'balanceCents' else null end,'materialCount',materials,'materialCost',material_cost,'materialDigest',material_digest,'basis',basis,'multipleWorks',v_work_id is null and related>1,'sharedQuote',related>1);
 select id into existing from pro_invoice_drafts where user_id=p_user and (source_kind=p_kind and source_id=p_id or quote_origin is not null and quote_origin_key=quote_origin) order by created_at,id limit 1;
 return v||jsonb_build_object('fingerprint',md5(v::text),'existingId',existing);
end $$;

create or replace function public.pro_invoice_copy_details(p_user uuid,p_draft uuid,p_source jsonb) returns void
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 delete from pro_invoice_lines where user_id=p_user and draft_id=p_draft;
 insert into pro_invoice_lines(user_id,draft_id,line_number,description,quantity,unit_amount,tax_rate)
 select p_user,p_draft,n,r->>'description',(r->>'quantity')::numeric,(r->>'unitAmount')::numeric,(r->>'taxRate')::numeric from jsonb_array_elements(p_source->'lines') with ordinality e(r,n);
 delete from pro_invoice_materials where user_id=p_user and draft_id=p_draft;
 insert into pro_invoice_materials(user_id,draft_id,entry_id,product_id,name,quantity,unit_cost)
 select p_user,p_draft,e.id,e.product_id,e.label,e.quantity,e.unit_cost from pro_client_entries e where e.user_id=p_user and e.work_id=p_source->>'workId' and e.kind='material' and not exists(select 1 from pro_client_entries r where r.user_id=e.user_id and r.reversal_id=e.id);
end $$;
create or replace function public.pro_invoice_draft_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare d pro_invoice_drafts;s jsonb;c pro_clients;receiver jsonb:=p_input->'receiver'; draft_id uuid;v_total bigint;kind text;source_id text;client_id text;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if p_input->>'action'='create' then kind:=p_input->>'kind';source_id:=p_input->>'sourceId';
 elsif p_input->>'action' in ('update','refresh') then
  select * into d from pro_invoice_drafts where user_id=p_user and id=(p_input->>'id')::uuid for update;
  if d.id is null then raise exception 'Missing draft' using errcode='22023';end if;
  if d.revision<>(p_input->>'revision')::integer then raise exception 'Draft revision changed' using errcode='40001';end if;
  kind:=d.source_kind;source_id:=d.source_id;
 else raise exception 'Only local draft actions are allowed' using errcode='22023';end if;
 if p_input->>'action'='update' then
  update pro_invoice_drafts set title=p_input->>'title',notes=p_input->>'notes',receiver_name=receiver->>'name',receiver_identification=receiver->>'identification',receiver_email=receiver->>'email',receiver_phone=receiver->>'phone',receiver_address=receiver->>'address',revision=revision+1,updated_at=now() where user_id=p_user and id=d.id;
  return d.id;
 end if;
 -- Standard quotes use their own writer: lock that row before taking the source snapshot.
 if kind='quote' then perform 1 from quotes where id::text=source_id for share;
 elsif kind='work' then perform 1 from quotes where id::text=(select "externalQuoteId" from pro_work where user_id=p_user and id=source_id) for share;end if;
 s:=pro_invoice_source(p_user,kind,source_id);
 if s is null or (s->>'multipleWorks')::boolean then raise exception 'Source unavailable or ambiguous' using errcode='22023';end if;
 if p_input->>'action'='create' and s->>'existingId' is not null then return (s->>'existingId')::uuid;end if;
 if s->>'fingerprint' is distinct from p_input->>'fingerprint' then raise exception 'Source changed' using errcode='40001';end if;
 if p_input->>'action'='create' then
  client_id:=p_input->>'clientId';
  if s->>'clientId' is not null and s->>'clientId'<>client_id then raise exception 'Client mismatch' using errcode='22023';end if;
  select * into c from pro_clients where user_id=p_user and id=client_id and not archived;
  if c.id is null then raise exception 'Invalid client' using errcode='22023';end if;
  draft_id:=gen_random_uuid();
 else
  client_id:=d.client_id;draft_id:=d.id;
  if s->>'clientId' is not null and s->>'clientId'<>d.client_id then raise exception 'Client changed; preserve original draft' using errcode='22023';end if;
 end if;
 v_total:=(s->>'totalCents')::bigint;
 if v_total is null then
  if p_input->>'action'='refresh' and d.basis<>'manual' then raise exception 'Define an individual work agreement before refreshing' using errcode='22023';end if;
  v_total:=case when p_input->>'action'='create' then (p_input->>'manualTotalCents')::bigint else d.total_cents end;
  if v_total is null or v_total<0 or v_total>10000000000 then raise exception 'Define draft total' using errcode='22023';end if;
  s:=jsonb_set(s,'{lines}',jsonb_build_array(jsonb_build_object('description',s->>'title','quantity',1,'unitAmount',v_total::numeric/100,'taxRate',null)));
 end if;
 if p_input->>'action'='create' then
  insert into pro_invoice_drafts(user_id,id,client_id,source_kind,source_id,work_id,quote_origin_key,title,notes,receiver_name,receiver_identification,receiver_email,receiver_phone,receiver_address,total_cents,tax_cents,agreed_cents,paid_cents,balance_cents,material_count,material_cost,basis,source_fingerprint)
  values(p_user,draft_id,client_id,s->>'kind',s->>'sourceId',s->>'workId',s->>'quoteOriginKey',p_input->>'title',p_input->>'notes',receiver->>'name',receiver->>'identification',receiver->>'email',receiver->>'phone',receiver->>'address',v_total,(s->>'taxCents')::bigint,(s->>'agreedCents')::bigint,(s->>'paidCents')::bigint,(s->>'balanceCents')::bigint,(s->>'materialCount')::integer,(s->>'materialCost')::numeric,s->>'basis',s->>'fingerprint');
 else
  update pro_invoice_drafts set source_kind=s->>'kind',source_id=s->>'sourceId',work_id=s->>'workId',quote_origin_key=s->>'quoteOriginKey',total_cents=v_total,tax_cents=(s->>'taxCents')::bigint,agreed_cents=(s->>'agreedCents')::bigint,paid_cents=(s->>'paidCents')::bigint,balance_cents=(s->>'balanceCents')::bigint,material_count=(s->>'materialCount')::integer,material_cost=(s->>'materialCost')::numeric,basis=s->>'basis',source_fingerprint=s->>'fingerprint',revision=revision+1,updated_at=now() where user_id=p_user and id=d.id;
 end if;
 perform pro_invoice_copy_details(p_user,draft_id,s);
 return draft_id;
end $$;
create or replace function public.pro_invoice_draft_read(p_user uuid,p_id uuid,p_after jsonb default null) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with draft as (select d.*,pro_invoice_source(p_user,d.source_kind,d.source_id) as current_source from pro_invoice_drafts d where user_id=p_user and id=p_id),
 materials as (select * from pro_invoice_materials where user_id=p_user and draft_id=p_id and (p_after is null or entry_id>(p_after->>'entryId')::uuid) order by entry_id limit 21)
 select jsonb_build_object('id',id,'clientId',client_id,'kind',source_kind,'sourceId',source_id,'title',title,'notes',notes,'receiver',jsonb_build_object('name',receiver_name,'identification',receiver_identification,'email',receiver_email,'phone',receiver_phone,'address',receiver_address),'revision',revision,'totalCents',total_cents,'taxCents',tax_cents,'agreedCents',agreed_cents,'paidCents',paid_cents,'balanceCents',balance_cents,'materialCount',material_count,'materialCost',material_cost,'basis',basis,'createdAt',created_at,'updatedAt',updated_at,
 'lines',coalesce((select jsonb_agg(jsonb_build_object('description',description,'quantity',quantity,'unitAmount',unit_amount,'taxRate',tax_rate) order by line_number) from pro_invoice_lines where user_id=p_user and draft_id=p_id),'[]'),
 'materials',coalesce((select jsonb_agg(jsonb_build_object('entryId',entry_id,'productId',product_id,'name',name,'quantity',quantity,'unitCost',unit_cost) order by entry_id) from (select * from materials order by entry_id limit 20) m),'[]'),
 'nextCursor',case when (select count(*) from materials)>20 then (select jsonb_build_object('entryId',entry_id) from materials order by entry_id offset 19 limit 1) else null end,
 'sourceNeedsAmount',current_source is not null and current_source->>'totalCents' is null and basis<>'manual','sourceAvailable',current_source is not null,'sourceChanged',current_source is null or current_source->>'fingerprint'<>source_fingerprint,'currentFingerprint',current_source->>'fingerprint') from draft;
$$;
revoke all on function pro_invoice_source(uuid,text,text),pro_invoice_copy_details(uuid,uuid,jsonb),pro_invoice_draft_save(uuid,jsonb),pro_invoice_draft_read(uuid,uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_invoice_source(uuid,text,text),pro_invoice_copy_details(uuid,uuid,jsonb),pro_invoice_draft_save(uuid,jsonb),pro_invoice_draft_read(uuid,uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== invoice-list-local.sql =====
-- LOCAL ONLY. Bounded, owner-scoped draft discovery; no operational mutations.
begin;
create index if not exists pro_invoice_draft_recent on public.pro_invoice_drafts(user_id,created_at desc,id desc);
create or replace function public.pro_invoice_draft_page(p_user uuid,p_search text default '',p_after jsonb default null) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with context as (
  select d.*,c.name as client_name,w.service as work_title,
   coalesce(l.title,q.title) as quote_title
  from pro_invoice_drafts d
  join pro_clients c on c.user_id=d.user_id and c.id=d.client_id
  left join pro_work w on w.user_id=d.user_id and w.id=d.work_id
  left join pro_legacy_quotes l on l.user_id=d.user_id and l.id=coalesce(w."quoteId",case when d.source_kind='legacy_quote' then d.source_id when d.quote_origin_key like 'legacy_quote:%' then substr(d.quote_origin_key,14) end)
  left join quotes q on q.id::text=coalesce(w."externalQuoteId",case when d.source_kind='quote' then d.source_id when d.quote_origin_key like 'quote:%' then substr(d.quote_origin_key,7) end)
   and exists(select 1 from professionals p where p.id=q.professional_id and p.profile_id=p_user)
  where d.user_id=p_user
 ), matches as (
  select * from context
  where strpos(pro_catalog_search(concat_ws(' ',title,receiver_name,client_name,work_title,quote_title)),pro_catalog_search(trim(p_search)))>0
   and (p_after is null or (created_at,id)<((p_after->>'at')::timestamptz,(p_after->>'id')::uuid))
  order by created_at desc,id desc limit 21
 ), page as (select * from matches order by created_at desc,id desc limit 20)
 select jsonb_build_object('rows',coalesce((select jsonb_agg(jsonb_build_object('id',id,'title',title,'receiver',receiver_name,'client',client_name,'clientId',client_id,'work',work_title,'quote',quote_title,'totalCents',total_cents,'createdAt',created_at,'updatedAt',updated_at) order by created_at desc,id desc) from page),'[]'),
 'nextCursor',case when (select count(*) from matches)>20 then (select jsonb_build_object('at',created_at,'id',id) from page order by created_at,id limit 1) else null end);
$$;
revoke all on function pro_invoice_draft_page(uuid,text,jsonb) from public,anon,authenticated;
grant execute on function pro_invoice_draft_page(uuid,text,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== invoice-preparation-local.sql =====
-- LOCAL ONLY. Optional draft preparation; never fiscal authorization or payment settlement.
begin;
create table if not exists public.pro_invoice_preparation(
 user_id uuid not null,draft_id uuid not null,
 issuer_name text not null check(length(issuer_name)<=160),
 issuer_id_type text not null check(issuer_id_type in ('','individual','company','dimex','nite','foreign')),
 issuer_id text not null check(length(issuer_id)<=40),issuer_email text not null check(length(issuer_email)<=254),
 issuer_phone text not null check(length(issuer_phone)<=30),issuer_address text not null check(length(issuer_address)<=500),
 issuer_activity text not null check(issuer_activity='' or issuer_activity ~ '^[0-9.]{1,12}$'),
 planned_date date,sale_condition text not null check(sale_condition in ('','cash','credit')),
 credit_days integer not null check(credit_days between 0 and 3650),
 payment_method text not null check(payment_method in ('','cash','card','transfer','sinpe','other')),
 order_reference text not null check(length(order_reference)<=80),
 primary key(user_id,draft_id),foreign key(user_id,draft_id) references public.pro_invoice_drafts(user_id,id) on delete cascade,
 check((sale_condition='credit' and credit_days>=1 and planned_date is not null) or (sale_condition<>'credit' and credit_days=0))
);
alter table pro_invoice_preparation enable row level security;
drop policy if exists pro_invoice_preparation_owner on pro_invoice_preparation;
create policy pro_invoice_preparation_owner on pro_invoice_preparation for select to authenticated using(user_id=auth.uid());
revoke all on pro_invoice_preparation from public,anon,authenticated;
grant select on pro_invoice_preparation to authenticated;
grant all on pro_invoice_preparation to service_role;
create or replace function public.pro_invoice_full_read(p_user uuid,p_id uuid,p_after jsonb default null) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select pro_invoice_draft_read(p_user,p_id,p_after)||jsonb_build_object('preparation',(
 select jsonb_build_object('issuerName',issuer_name,'issuerIdType',issuer_id_type,'issuerId',issuer_id,'issuerEmail',issuer_email,'issuerPhone',issuer_phone,'issuerAddress',issuer_address,'issuerActivity',issuer_activity,'plannedDate',coalesce(planned_date::text,''),'saleCondition',sale_condition,'creditDays',credit_days,'paymentMethod',payment_method,'orderReference',order_reference)
 from pro_invoice_preparation where user_id=p_user and draft_id=p_id));
$$;
create or replace function public.pro_invoice_full_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare saved uuid;existing text;v jsonb:=p_input->'preparation';
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if p_input->>'action'='create' then existing:=pro_invoice_source(p_user,p_input->>'kind',p_input->>'sourceId')->>'existingId';end if;
 saved:=pro_invoice_draft_save(p_user,p_input);
 -- A retry of create must never overwrite any existing snapshot or receiver.
 if existing is not null or not(p_input ? 'preparation') then return saved;end if;
 if p_input->>'action' not in ('create','update') or jsonb_typeof(v)<>'object' then raise exception 'Invalid preparation' using errcode='22023';end if;
 insert into pro_invoice_preparation(user_id,draft_id,issuer_name,issuer_id_type,issuer_id,issuer_email,issuer_phone,issuer_address,issuer_activity,planned_date,sale_condition,credit_days,payment_method,order_reference)
 values(p_user,saved,v->>'issuerName',v->>'issuerIdType',v->>'issuerId',v->>'issuerEmail',v->>'issuerPhone',v->>'issuerAddress',v->>'issuerActivity',nullif(v->>'plannedDate','')::date,v->>'saleCondition',(v->>'creditDays')::integer,v->>'paymentMethod',v->>'orderReference')
 on conflict(user_id,draft_id) do update set issuer_name=excluded.issuer_name,issuer_id_type=excluded.issuer_id_type,issuer_id=excluded.issuer_id,issuer_email=excluded.issuer_email,issuer_phone=excluded.issuer_phone,issuer_address=excluded.issuer_address,issuer_activity=excluded.issuer_activity,planned_date=excluded.planned_date,sale_condition=excluded.sale_condition,credit_days=excluded.credit_days,payment_method=excluded.payment_method,order_reference=excluded.order_reference;
 return saved;
end $$;
revoke all on function pro_invoice_full_read(uuid,uuid,jsonb),pro_invoice_full_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_invoice_full_read(uuid,uuid,jsonb),pro_invoice_full_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== invoice-detail-local.sql =====
-- LOCAL ONLY. Editable commercial draft detail, separate from source snapshots and operational ledgers.
begin;
create table if not exists public.pro_invoice_edited_detail(
 user_id uuid not null,draft_id uuid not null,source_total_cents bigint not null,source_tax_cents bigint,
 gross numeric not null,discount numeric not null,net numeric not null,tax numeric not null,total numeric not null,
 calculation_version text not null default 'crc-draft-v1' check(calculation_version='crc-draft-v1'),
 primary key(user_id,draft_id),foreign key(user_id,draft_id) references pro_invoice_drafts(user_id,id) on delete cascade
);
create table if not exists public.pro_invoice_edited_lines(
 user_id uuid not null,draft_id uuid not null,line_number integer not null check(line_number between 1 and 100),
 kind text not null check(kind in ('pending','product','service')),product_id text,sku text not null check(length(sku)<=160),
 description text not null check(length(trim(description)) between 1 and 200),unit text not null check(length(unit)<=30),cabys text not null check(cabys='' or cabys ~ '^[0-9]{13}$'),
 quantity numeric not null check(quantity>0 and quantity<=1000000 and quantity=round(quantity,5)),
 unit_price numeric not null check(unit_price between 0 and 100000000 and unit_price=round(unit_price,5)),
 discount_type text not null check(discount_type in ('percent','amount')),discount numeric not null check(discount>=0 and discount<=100000000 and discount=round(discount,5)),discount_reason text not null check(length(discount_reason)<=160),
 tax_treatment text not null check(tax_treatment in ('pending','vat','exempt','not_subject')),tax_rate numeric not null check(tax_rate between 0 and 100 and tax_rate=round(tax_rate,5)),
 primary key(user_id,draft_id,line_number),foreign key(user_id,draft_id) references pro_invoice_edited_detail(user_id,draft_id) on delete cascade,
 foreign key(user_id,product_id) references pro_products(user_id,id) on delete set null (product_id),
 check(product_id is null or kind='product'),check(discount_type<>'percent' or discount<=100),check(tax_treatment='vat' or tax_rate=0),
 check(discount_type<>'amount' or discount<=round(quantity*unit_price,5))
);
-- Retain the invoice snapshot if a catalog item is hard-deleted, including owner cascades.
alter table pro_invoice_edited_lines drop constraint if exists pro_invoice_edited_lines_user_id_product_id_fkey;
alter table pro_invoice_edited_lines add constraint pro_invoice_edited_lines_user_id_product_id_fkey foreign key(user_id,product_id) references pro_products(user_id,id) on delete set null (product_id);
alter table pro_invoice_edited_detail enable row level security;
alter table pro_invoice_edited_lines enable row level security;
drop policy if exists pro_invoice_edited_detail_owner on pro_invoice_edited_detail;
drop policy if exists pro_invoice_edited_lines_owner on pro_invoice_edited_lines;
create policy pro_invoice_edited_detail_owner on pro_invoice_edited_detail for select to authenticated using(user_id=auth.uid());
create policy pro_invoice_edited_lines_owner on pro_invoice_edited_lines for select to authenticated using(user_id=auth.uid());
revoke all on pro_invoice_edited_detail,pro_invoice_edited_lines from public,anon,authenticated;
grant select on pro_invoice_edited_detail,pro_invoice_edited_lines to authenticated;
grant all on pro_invoice_edited_detail,pro_invoice_edited_lines to service_role;
create or replace function public.pro_invoice_editable_read(p_user uuid,p_id uuid,p_after jsonb default null) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select pro_invoice_full_read(p_user,p_id,p_after)||jsonb_build_object('editedDetail',(
 select jsonb_build_object('sourceTotalCents',source_total_cents,'sourceTaxCents',source_tax_cents,'gross',gross::text,'discount',discount::text,'net',net::text,'tax',tax::text,'total',total::text,'version',calculation_version,
 'lines',(select jsonb_agg(jsonb_build_object('kind',kind,'productId',product_id,'sku',sku,'description',description,'unit',unit,'cabys',cabys,'quantity',quantity::text,'unitPrice',unit_price::text,'discountType',discount_type,'discount',discount::text,'discountReason',discount_reason,'taxTreatment',tax_treatment,'taxRate',tax_rate::text) order by line_number) from pro_invoice_edited_lines where user_id=p_user and draft_id=p_id))
 from pro_invoice_edited_detail where user_id=p_user and draft_id=p_id));
$$;
create or replace function public.pro_invoice_editable_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare d pro_invoice_drafts;h pro_invoice_edited_detail;saved uuid;v_gross numeric;v_discount numeric;v_net numeric;v_tax numeric;v_total numeric;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if p_input->>'action' in ('detail','reset_detail') then
  select * into d from pro_invoice_drafts where user_id=p_user and id=(p_input->>'id')::uuid for update;
  if d.id is null then raise exception 'Missing draft' using errcode='22023';end if;
  if d.revision<>(p_input->>'revision')::integer then raise exception 'Draft changed' using errcode='40001';end if;
  select * into h from pro_invoice_edited_detail where user_id=p_user and draft_id=d.id;
  if p_input->>'action'='reset_detail' then
   if h.draft_id is null then return d.id;end if;
   update pro_invoice_drafts set total_cents=h.source_total_cents,tax_cents=h.source_tax_cents,revision=revision+1,updated_at=now() where user_id=p_user and id=d.id;
   delete from pro_invoice_edited_detail where user_id=p_user and draft_id=d.id;
   return d.id;
  end if;
  if jsonb_typeof(p_input->'lines') is distinct from 'array' or jsonb_array_length(p_input->'lines') not between 1 and 100 then raise exception 'Invalid detail' using errcode='22023';end if;
  insert into pro_invoice_edited_detail(user_id,draft_id,source_total_cents,source_tax_cents,gross,discount,net,tax,total)
   values(p_user,d.id,d.total_cents,d.tax_cents,0,0,0,0,0) on conflict(user_id,draft_id) do nothing;
  delete from pro_invoice_edited_lines where user_id=p_user and draft_id=d.id;
  insert into pro_invoice_edited_lines(user_id,draft_id,line_number,kind,product_id,sku,description,unit,cabys,quantity,unit_price,discount_type,discount,discount_reason,tax_treatment,tax_rate)
  select p_user,d.id,n,r->>'kind',r->>'productId',r->>'sku',r->>'description',r->>'unit',r->>'cabys',replace(r->>'quantity',',','.')::numeric,replace(r->>'unitPrice',',','.')::numeric,r->>'discountType',replace(r->>'discount',',','.')::numeric,r->>'discountReason',r->>'taxTreatment',replace(r->>'taxRate',',','.')::numeric from jsonb_array_elements(p_input->'lines') with ordinality e(r,n);
  with gross_lines as (select *,round(quantity*unit_price,5) as gross from pro_invoice_edited_lines where user_id=p_user and draft_id=d.id),
  discounted as (select *,case when discount_type='percent' then round(gross*discount/100,5) else discount end as reduction from gross_lines),
  priced as (select *,gross-reduction as base,case when tax_treatment='vat' then round((gross-reduction)*tax_rate/100,5) else 0 end as iva from discounted)
  select sum(gross),sum(reduction),sum(base),sum(iva),sum(base+iva) into v_gross,v_discount,v_net,v_tax,v_total from priced;
  update pro_invoice_edited_detail set gross=v_gross,discount=v_discount,net=v_net,tax=v_tax,total=v_total where user_id=p_user and draft_id=d.id;
  update pro_invoice_drafts set total_cents=round(v_total*100),tax_cents=round(v_tax*100),revision=revision+1,updated_at=now() where user_id=p_user and id=d.id;
  return d.id;
 end if;
 if p_input->>'action'='refresh' then
  select * into h from pro_invoice_edited_detail where user_id=p_user and draft_id=(p_input->>'id')::uuid;
  -- The legacy refresher retains the saved amount for an unpriced/manual job.
  -- Give it the source amount, never the edited invoice amount, for that rule.
  if h.draft_id is not null then update pro_invoice_drafts set total_cents=h.source_total_cents,tax_cents=h.source_tax_cents where user_id=p_user and id=h.draft_id;end if;
 end if;
 saved:=pro_invoice_full_save(p_user,p_input);
 if p_input->>'action'='refresh' then
  select * into h from pro_invoice_edited_detail where user_id=p_user and draft_id=saved;
  if h.draft_id is not null then
   update pro_invoice_edited_detail set source_total_cents=draft.total_cents,source_tax_cents=draft.tax_cents from pro_invoice_drafts draft where pro_invoice_edited_detail.user_id=p_user and pro_invoice_edited_detail.draft_id=saved and draft.user_id=p_user and draft.id=saved;
   update pro_invoice_drafts set total_cents=round(h.total*100),tax_cents=round(h.tax*100) where user_id=p_user and id=saved;
  end if;
 end if;
 return saved;
end $$;
revoke all on function pro_invoice_editable_read(uuid,uuid,jsonb),pro_invoice_editable_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_invoice_editable_read(uuid,uuid,jsonb),pro_invoice_editable_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== invoice-direct-local.sql =====
-- LOCAL ONLY. Direct drafts, no artificial work/quote, stock writes or fiscal issuance.
begin;
alter table pro_invoice_drafts drop constraint if exists pro_invoice_drafts_source_kind_check;
alter table pro_invoice_drafts add constraint pro_invoice_drafts_source_kind_check check(source_kind in ('work','quote','legacy_quote','direct'));
alter table pro_invoice_drafts drop constraint if exists pro_invoice_drafts_direct_check;
alter table pro_invoice_drafts add constraint pro_invoice_drafts_direct_check check(source_kind<>'direct' or (source_id=id::text and work_id is null and quote_origin_key is null and basis='manual' and agreed_cents is null and paid_cents is null and balance_cents is null and material_count=0 and material_cost=0));
create or replace function public.pro_invoice_direct_read(p_user uuid,p_id uuid,p_after jsonb default null) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select pro_invoice_editable_read(p_user,p_id,p_after)||case when exists(select 1 from pro_invoice_drafts where user_id=p_user and id=p_id and source_kind='direct') then jsonb_build_object('sourceAvailable',false,'sourceChanged',false,'sourceNeedsAmount',false,'currentFingerprint',null) else '{}'::jsonb end;
$$;
create or replace function public.pro_invoice_direct_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare d pro_invoice_drafts;c pro_clients;v_id uuid;v_hash text;v_saved uuid;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if p_input->>'action'='create_direct' then
  v_id:=(p_input->>'requestId')::uuid;
  v_hash:=md5((p_input-'requestId')::text);
  select * into d from pro_invoice_drafts where user_id=p_user and id=v_id;
  if d.id is not null then
   if d.source_kind<>'direct' or d.source_fingerprint<>v_hash then raise exception 'Request already used; recover saved draft' using errcode='40001';end if;
   return d.id;
  end if;
  select * into c from pro_clients where user_id=p_user and id=p_input->>'clientId' and not archived for share;
  if c.id is null then raise exception 'Choose an active owned client' using errcode='22023';end if;
  if exists(select 1 from jsonb_array_elements(p_input->'lines') e where e->>'productId' is not null and not exists(select 1 from pro_products p where p.user_id=p_user and p.id=e->>'productId' and not p.archived)) then raise exception 'Invalid catalog item' using errcode='22023';end if;
  insert into pro_invoice_drafts(user_id,id,client_id,source_kind,source_id,title,notes,receiver_name,receiver_identification,receiver_email,receiver_phone,receiver_address,total_cents,tax_cents,material_count,material_cost,basis,source_fingerprint)
  values(p_user,v_id,c.id,'direct',v_id::text,p_input->>'title',p_input->>'notes',c.name,coalesce(c.identification,''),c.email,c.phone,coalesce(c.address,''),0,0,0,0,'manual',v_hash);
  -- Reuse the exact same monetary writer in this transaction. Failure rolls back the header too.
  v_saved:=pro_invoice_editable_save(p_user,jsonb_build_object('action','detail','id',v_id,'revision',1,'lines',p_input->'lines'));
  return v_saved;
 end if;
 if p_input->>'action' in ('refresh','reset_detail') and exists(select 1 from pro_invoice_drafts where user_id=p_user and id=(p_input->>'id')::uuid and source_kind='direct') then raise exception 'Direct drafts have no source to restore' using errcode='22023';end if;
 return pro_invoice_editable_save(p_user,p_input);
end $$;
revoke all on function pro_invoice_direct_read(uuid,uuid,jsonb),pro_invoice_direct_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_invoice_direct_read(uuid,uuid,jsonb),pro_invoice_direct_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== invoice-issuer-local.sql =====
-- LOCAL ONLY. Reusable issuer, copied only to newly created drafts. No historical backfill.
begin;
create table if not exists public.pro_invoice_issuer_settings(
 user_id uuid primary key references profiles(id) on delete cascade,
 issuer_name text not null check(length(trim(issuer_name)) between 1 and 160),
 issuer_id_type text not null check(issuer_id_type in ('','individual','company','dimex','nite','foreign')),
 issuer_id text not null check(length(issuer_id)<=40),issuer_email text not null check(length(issuer_email)<=254),
 issuer_phone text not null check(length(issuer_phone)<=30),issuer_address text not null check(length(issuer_address)<=500),
 issuer_activity text not null check(issuer_activity='' or issuer_activity ~ '^[0-9.]{1,12}$'),
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default now()
);
alter table pro_invoice_issuer_settings enable row level security;
drop policy if exists pro_invoice_issuer_owner on pro_invoice_issuer_settings;
create policy pro_invoice_issuer_owner on pro_invoice_issuer_settings for select to authenticated using(user_id=auth.uid());
revoke all on pro_invoice_issuer_settings from public,anon,authenticated;
grant select on pro_invoice_issuer_settings to authenticated;
grant all on pro_invoice_issuer_settings to service_role;
create or replace function public.pro_invoice_issuer_read(p_user uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce((select jsonb_build_object('revision',revision,'issuer',jsonb_build_object('issuerName',issuer_name,'issuerIdType',issuer_id_type,'issuerId',issuer_id,'issuerEmail',issuer_email,'issuerPhone',issuer_phone,'issuerAddress',issuer_address,'issuerActivity',issuer_activity)) from pro_invoice_issuer_settings where user_id=p_user),jsonb_build_object('revision',0,'issuer',jsonb_build_object('issuerName','','issuerIdType','','issuerId','','issuerEmail','','issuerPhone','','issuerAddress','','issuerActivity','')));
$$;
create or replace function public.pro_invoice_issuer_save(p_user uuid,p_revision integer,p_issuer jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare current_revision integer;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 select revision into current_revision from pro_invoice_issuer_settings where user_id=p_user for update;
 if p_revision is null or p_revision<0 or coalesce(current_revision,0)<>p_revision then raise exception 'Issuer settings changed' using errcode='40001';end if;
 insert into pro_invoice_issuer_settings(user_id,issuer_name,issuer_id_type,issuer_id,issuer_email,issuer_phone,issuer_address,issuer_activity)
 values(p_user,p_issuer->>'issuerName',p_issuer->>'issuerIdType',p_issuer->>'issuerId',p_issuer->>'issuerEmail',p_issuer->>'issuerPhone',p_issuer->>'issuerAddress',p_issuer->>'issuerActivity')
 on conflict(user_id) do update set issuer_name=excluded.issuer_name,issuer_id_type=excluded.issuer_id_type,issuer_id=excluded.issuer_id,issuer_email=excluded.issuer_email,issuer_phone=excluded.issuer_phone,issuer_address=excluded.issuer_address,issuer_activity=excluded.issuer_activity,revision=pro_invoice_issuer_settings.revision+1,updated_at=now();
 return pro_invoice_issuer_read(p_user);
end $$;
create or replace function public.pro_invoice_configured_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare existing uuid;saved uuid;config jsonb;d pro_invoice_drafts;prep jsonb;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if p_input->>'action'='create_direct' then select id into existing from pro_invoice_drafts where user_id=p_user and id=(p_input->>'requestId')::uuid;
 elsif p_input->>'action'='create' then existing:=(pro_invoice_source(p_user,p_input->>'kind',p_input->>'sourceId')->>'existingId')::uuid;end if;
 saved:=pro_invoice_direct_save(p_user,p_input);
 -- Never overwrite snapshots on retries, normal edits, detail edits or source refresh.
 if existing is not null or p_input->>'action' not in ('create','create_direct') or p_input ? 'preparation' then return saved;end if;
 config:=pro_invoice_issuer_read(p_user);
 if (config->>'revision')::integer=0 then return saved;end if;
 select * into d from pro_invoice_drafts where user_id=p_user and id=saved;
 prep:=(config->'issuer')||jsonb_build_object('plannedDate','','saleCondition','','creditDays',0,'paymentMethod','','orderReference','');
 perform pro_invoice_full_save(p_user,jsonb_build_object('action','update','id',saved,'revision',d.revision,'title',d.title,'notes',d.notes,'receiver',jsonb_build_object('name',d.receiver_name,'identification',d.receiver_identification,'email',d.receiver_email,'phone',d.receiver_phone,'address',d.receiver_address),'preparation',prep));
 return saved;
end $$;
revoke all on function pro_invoice_issuer_read(uuid),pro_invoice_issuer_save(uuid,integer,jsonb),pro_invoice_configured_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function pro_invoice_issuer_read(uuid),pro_invoice_issuer_save(uuid,integer,jsonb),pro_invoice_configured_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== client-fiscal-local.sql =====
-- LOCAL ONLY. Reusable client fiscal data and immutable-by-default draft snapshots.
-- Install after invoice-issuer-local.sql. No backfill, fiscal emission or base-source fingerprint changes.
begin;
create table if not exists public.pro_client_fiscal_settings(
 user_id uuid not null,client_id text not null,
 name text not null check(length(trim(name)) between 1 and 160),identification text not null check(length(identification)<=40),email text not null check(length(email)<=254),phone text not null check(length(phone)<=30),address text not null check(length(address)<=500),
 identification_type text not null check(identification_type in ('','individual','company','dimex','nite','foreign')),
 activity text not null check(activity='' or activity ~ '^[0-9.]{1,12}$'),
 province text not null check(length(province)<=80),
 canton text not null check(length(canton)<=80),
 district text not null check(length(district)<=80),
 neighborhood text not null check(length(neighborhood)<=100),
 revision integer not null default 1 check(revision>0),updated_at timestamptz not null default now(),
 primary key(user_id,client_id),foreign key(user_id,client_id) references public.pro_clients(user_id,id) on delete cascade
);
create table if not exists public.pro_invoice_receiver_fiscal(
 user_id uuid not null,draft_id uuid not null,
 identification_type text not null check(identification_type in ('','individual','company','dimex','nite','foreign')),
 activity text not null check(activity='' or activity ~ '^[0-9.]{1,12}$'),
 province text not null check(length(province)<=80),
 canton text not null check(length(canton)<=80),
 district text not null check(length(district)<=80),
 neighborhood text not null check(length(neighborhood)<=100),
 primary key(user_id,draft_id),foreign key(user_id,draft_id) references public.pro_invoice_drafts(user_id,id) on delete cascade
);
alter table public.pro_client_fiscal_settings enable row level security;
drop policy if exists pro_client_fiscal_settings_owner on public.pro_client_fiscal_settings;
create policy pro_client_fiscal_settings_owner on public.pro_client_fiscal_settings for select to authenticated using(user_id=(select auth.uid()));
revoke all on public.pro_client_fiscal_settings from public,anon,authenticated;
grant select on public.pro_client_fiscal_settings to authenticated;
grant all on public.pro_client_fiscal_settings to service_role;
alter table public.pro_invoice_receiver_fiscal enable row level security;
drop policy if exists pro_invoice_receiver_fiscal_owner on public.pro_invoice_receiver_fiscal;
create policy pro_invoice_receiver_fiscal_owner on public.pro_invoice_receiver_fiscal for select to authenticated using(user_id=(select auth.uid()));
revoke all on public.pro_invoice_receiver_fiscal from public,anon,authenticated;
grant select on public.pro_invoice_receiver_fiscal to authenticated;
grant all on public.pro_invoice_receiver_fiscal to service_role;
create or replace function public.pro_client_fiscal_read(p_user uuid,p_client text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('revision',coalesce(f.revision,0),'receiver',
 case when f.client_id is not null then jsonb_build_object('name',f.name,'identification',f.identification,'email',f.email,'phone',f.phone,'address',f.address,'identificationType',f.identification_type,'activity',f.activity,'province',f.province,'canton',f.canton,'district',f.district,'neighborhood',f.neighborhood)
 else jsonb_build_object('name',c.name,'identification',coalesce(c.identification,''),'email',c.email,'phone',c.phone,'address',coalesce(c.address,''),'identificationType','','activity','','province','','canton','','district','','neighborhood','') end)
 from pro_clients c left join pro_client_fiscal_settings f on f.user_id=c.user_id and f.client_id=c.id where c.user_id=p_user and c.id=p_client;
$$;
create or replace function public.pro_client_fiscal_save(p_user uuid,p_client text,p_revision integer,p_receiver jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare current_revision integer;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if not exists(select 1 from pro_clients where user_id=p_user and id=p_client and not archived) then raise exception 'Choose an active owned client' using errcode='22023';end if;
 select revision into current_revision from pro_client_fiscal_settings where user_id=p_user and client_id=p_client for update;
 if p_revision is null or p_revision<0 or coalesce(current_revision,0)<>p_revision then raise exception 'Client fiscal settings changed' using errcode='40001';end if;
 if jsonb_typeof(p_receiver) is distinct from 'object' then raise exception 'Invalid fiscal receiver' using errcode='22023';end if;
 insert into pro_client_fiscal_settings(user_id,client_id,name,identification,email,phone,address,identification_type,activity,province,canton,district,neighborhood) values(p_user,p_client,p_receiver->>'name',p_receiver->>'identification',p_receiver->>'email',p_receiver->>'phone',p_receiver->>'address',p_receiver->>'identificationType',p_receiver->>'activity',p_receiver->>'province',p_receiver->>'canton',p_receiver->>'district',p_receiver->>'neighborhood')
 on conflict(user_id,client_id) do update set name=excluded.name,identification=excluded.identification,email=excluded.email,phone=excluded.phone,address=excluded.address,identification_type=excluded.identification_type,activity=excluded.activity,province=excluded.province,canton=excluded.canton,district=excluded.district,neighborhood=excluded.neighborhood,revision=pro_client_fiscal_settings.revision+1,updated_at=now();
 return pro_client_fiscal_read(p_user,p_client);
end $$;
create or replace function public.pro_invoice_fiscal_read(p_user uuid,p_id uuid,p_after jsonb default null) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select case when b.document is null then null else b.document||case when f.draft_id is null then '{}'::jsonb else jsonb_build_object('receiver',b.document->'receiver'||jsonb_build_object('identificationType',f.identification_type,'activity',f.activity,'province',f.province,'canton',f.canton,'district',f.district,'neighborhood',f.neighborhood)) end end
 from (select pro_invoice_direct_read(p_user,p_id,p_after) as document) b left join pro_invoice_receiver_fiscal f on f.user_id=p_user and f.draft_id=p_id;
$$;
create or replace function public.pro_invoice_fiscal_source(p_user uuid,p_kind text,p_id text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare source jsonb;config jsonb;
begin
 source:=pro_invoice_source(p_user,p_kind,p_id);
 if source is null then return null;end if;
 if source->>'clientId' is not null then config:=pro_client_fiscal_read(p_user,source->>'clientId');end if;
 -- Keep the base fingerprint: the original writer independently verifies that exact source.
 -- The receiver shown in this preview must be sent explicitly on create and is snapshotted.
 if config is not null then source:=jsonb_set(source,'{receiver}',config->'receiver');end if;
 return source;
end $$;
create or replace function public.pro_invoice_fiscal_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare existing uuid;saved uuid;receiver jsonb;config jsonb;d pro_invoice_drafts;action text:=p_input->>'action';
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if action='create_direct' then select id into existing from pro_invoice_drafts where user_id=p_user and id=(p_input->>'requestId')::uuid;
 elsif action='create' then existing:=(pro_invoice_source(p_user,p_input->>'kind',p_input->>'sourceId')->>'existingId')::uuid;end if;
 -- Pass raw input unchanged. Direct request fingerprints include every input property.
 saved:=pro_invoice_configured_save(p_user,p_input);
 if existing is not null then return saved;end if;
 if action='create_direct' then
  select * into d from pro_invoice_drafts where user_id=p_user and id=saved;
  config:=pro_client_fiscal_read(p_user,d.client_id);
  if (config->>'revision')::integer=0 then return saved;end if;
  receiver:=config->'receiver';
  if receiver is null then raise exception 'Missing client receiver' using errcode='22023';end if;
  -- The original direct creator already incremented the revision; this remains one atomic creation.
  update pro_invoice_drafts set receiver_name=receiver->>'name',receiver_identification=receiver->>'identification',receiver_email=receiver->>'email',receiver_phone=receiver->>'phone',receiver_address=receiver->>'address' where user_id=p_user and id=saved;
 elsif action in ('create','update') and (p_input->'receiver') ? 'identificationType' then receiver:=p_input->'receiver';
 else return saved;end if;
 -- New fields only; old callers and source refresh cannot erase an existing snapshot.
 insert into pro_invoice_receiver_fiscal(user_id,draft_id,identification_type,activity,province,canton,district,neighborhood) values(p_user,saved,receiver->>'identificationType',receiver->>'activity',receiver->>'province',receiver->>'canton',receiver->>'district',receiver->>'neighborhood')
 on conflict(user_id,draft_id) do update set identification_type=excluded.identification_type,activity=excluded.activity,province=excluded.province,canton=excluded.canton,district=excluded.district,neighborhood=excluded.neighborhood;
 return saved;
end $$;
revoke all on function public.pro_client_fiscal_read(uuid,text),public.pro_client_fiscal_save(uuid,text,integer,jsonb),public.pro_invoice_fiscal_read(uuid,uuid,jsonb),public.pro_invoice_fiscal_source(uuid,text,text),public.pro_invoice_fiscal_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_client_fiscal_read(uuid,text),public.pro_client_fiscal_save(uuid,text,integer,jsonb),public.pro_invoice_fiscal_read(uuid,uuid,jsonb),public.pro_invoice_fiscal_source(uuid,text,text),public.pro_invoice_fiscal_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== invoice-tax-local.sql =====
-- LOCAL ONLY. Explicit ordinary IVA and documentary exoneration snapshots; no fiscal emission/backfill.
-- Install after client-fiscal-local.sql. Raw direct-create inputs retain their original request hashes.
begin;
alter table public.pro_invoice_edited_detail drop constraint if exists pro_invoice_edited_detail_calculation_version_check;
alter table public.pro_invoice_edited_detail add constraint pro_invoice_edited_detail_calculation_version_check check(calculation_version in ('crc-draft-v1','crc-draft-tax-v2','crc-draft-extras-v3','crc-draft-extras-v4'));
create table if not exists public.pro_invoice_line_tax(
 user_id uuid not null,draft_id uuid not null,line_number integer not null,
 vat_code text not null check(vat_code in ('01','02','03','04','08','09','10','11')),
 exemption_document_type text check(exemption_document_type in ('02','03','04','08','09','10','99')),
 exemption_document_other text,exemption_document_number text,exemption_article text,exemption_paragraph text,
 exemption_institution text,exemption_institution_other text,exemption_issued_on date,exemption_rate numeric,
 primary key(user_id,draft_id,line_number),
 foreign key(user_id,draft_id,line_number) references public.pro_invoice_edited_lines(user_id,draft_id,line_number) on delete cascade,
 check((exemption_document_type is null and num_nonnulls(exemption_document_other,exemption_document_number,exemption_article,exemption_paragraph,exemption_institution,exemption_institution_other,exemption_issued_on,exemption_rate)=0)
 or (exemption_document_type is not null and num_nulls(exemption_document_other,exemption_document_number,exemption_article,exemption_paragraph,exemption_institution,exemption_institution_other,exemption_issued_on,exemption_rate)=0)),
 check(exemption_document_type is null or length(trim(exemption_document_number)) between 3 and 40),
 check(exemption_document_type is null or case when exemption_document_type='99' then length(trim(exemption_document_other)) between 5 and 100 else exemption_document_other='' end),
 check(exemption_document_type is null or exemption_institution in ('01','02','03','04','05','06','07','08','09','10','11','12','99')),
 check(exemption_document_type is null or case when exemption_institution='99' then length(trim(exemption_institution_other)) between 5 and 160 else exemption_institution_other='' end),
 check(exemption_document_type is null or ((exemption_article='' and exemption_document_type not in ('02','03','08')) or (exemption_article ~ '^[0-9]{1,6}$' and exemption_article::integer>0))),
 check(exemption_document_type is null or exemption_paragraph='' or (exemption_article<>'' and exemption_paragraph ~ '^[0-9]{1,6}$')),
 check(exemption_document_type is null or (exemption_rate>0 and exemption_rate<=13 and exemption_rate=round(exemption_rate,2)))
);
-- Validate the ordinary code against the actual saved line, including zero-rate distinctions.
create or replace function public.pro_invoice_line_tax_validate() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare line pro_invoice_edited_lines;expected_rate numeric;
begin
 select * into line from pro_invoice_edited_lines where user_id=new.user_id and draft_id=new.draft_id and line_number=new.line_number;
 expected_rate:=case new.vat_code when '01' then 0 when '02' then 1 when '03' then 2 when '04' then 4 when '08' then 13 when '09' then 0.5 when '10' then 0 when '11' then 0 end;
 if line.draft_id is null or line.tax_rate is distinct from expected_rate or line.tax_treatment is distinct from (case new.vat_code when '10' then 'exempt' when '11' then 'not_subject' else 'vat' end) then raise exception 'Ordinary IVA code does not match line treatment/rate' using errcode='22023';end if;
 if new.exemption_document_type is not null and (line.tax_treatment<>'vat' or line.tax_rate<=0 or new.exemption_rate>line.tax_rate) then raise exception 'Exoneration exceeds positive IVA rate' using errcode='22023';end if;
 return new;
end $$;
drop trigger if exists pro_invoice_line_tax_validate on public.pro_invoice_line_tax;
create trigger pro_invoice_line_tax_validate before insert or update on public.pro_invoice_line_tax for each row execute function public.pro_invoice_line_tax_validate();
alter table public.pro_invoice_line_tax enable row level security;
drop policy if exists pro_invoice_line_tax_owner on public.pro_invoice_line_tax;
create policy pro_invoice_line_tax_owner on public.pro_invoice_line_tax for select to authenticated using(user_id=(select auth.uid()));
revoke all on public.pro_invoice_line_tax from public,anon,authenticated;
grant select on public.pro_invoice_line_tax to authenticated;
grant all on public.pro_invoice_line_tax to service_role;
create or replace function public.pro_invoice_tax_totals(p_user uuid,p_id uuid) returns table(gross_tax numeric,exonerated numeric)
language sql stable security invoker set search_path=public,pg_temp as $$
 with bases as (
 select l.*,t.exemption_rate,round(l.quantity*l.unit_price,5) as gross from pro_invoice_edited_lines l left join pro_invoice_line_tax t using(user_id,draft_id,line_number) where l.user_id=p_user and l.draft_id=p_id
 ), priced as (select *,gross-case when discount_type='percent' then round(gross*discount/100,5) else discount end as base from bases)
 select coalesce(sum(case when tax_treatment='vat' then round(base*tax_rate/100,5) else 0 end),0),coalesce(sum(case when exemption_rate is not null then round(base*exemption_rate/100,5) else 0 end),0) from priced;
$$;
create or replace function public.pro_invoice_tax_read(p_user uuid,p_id uuid,p_after jsonb default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare document jsonb;lines jsonb;gross_tax numeric;exonerated numeric;
begin
 document:=pro_invoice_fiscal_read(p_user,p_id,p_after);
 if document is null or not exists(select 1 from pro_invoice_line_tax where user_id=p_user and draft_id=p_id) then return document;end if;
 select jsonb_agg(e.value||case when t.line_number is null then jsonb_build_object('tax',null) else jsonb_build_object('tax',jsonb_build_object('vatCode',t.vat_code,'exemption',case when t.exemption_document_type is null then null else jsonb_build_object('documentType',t.exemption_document_type,'documentOther',t.exemption_document_other,'documentNumber',t.exemption_document_number,'article',t.exemption_article,'paragraph',t.exemption_paragraph,'institution',t.exemption_institution,'institutionOther',t.exemption_institution_other,'issuedOn',t.exemption_issued_on::text,'rate',t.exemption_rate::text) end)) end order by e.n)
 into lines from jsonb_array_elements(document->'editedDetail'->'lines') with ordinality e(value,n) left join pro_invoice_line_tax t on t.user_id=p_user and t.draft_id=p_id and t.line_number=e.n;
 select * into gross_tax,exonerated from pro_invoice_tax_totals(p_user,p_id);
 return jsonb_set(document,'{editedDetail}',document->'editedDetail'||jsonb_build_object('lines',lines,'grossTax',round(gross_tax,5)::text,'exonerated',round(exonerated,5)::text,'version','crc-draft-tax-v2'));
end $$;
create or replace function public.pro_invoice_tax_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare saved uuid;target uuid;action text:=p_input->>'action';entry record;tax jsonb;exemption jsonb;gross_tax numeric;exonerated numeric;has_tax boolean;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if action='create_direct' then
  target:=(p_input->>'requestId')::uuid;
  -- Delegate unchanged so the existing direct writer validates both owner and exact request fingerprint.
  if exists(select 1 from pro_invoice_drafts where user_id=p_user and id=target) then return pro_invoice_fiscal_save(p_user,p_input);end if;
 elsif action='detail' then target:=(p_input->>'id')::uuid;end if;
 if action='detail' and exists(select 1 from pro_invoice_line_tax where user_id=p_user and draft_id=target) and exists(select 1 from jsonb_array_elements(p_input->'lines') line where not(line ? 'tax')) then raise exception 'This editor cannot preserve saved exonerations; reload before replacing detail' using errcode='40001';end if;
 saved:=pro_invoice_fiscal_save(p_user,p_input);
 if action in ('detail','create_direct') then
  -- The underlying detail writer replaced lines and cascaded their former tax snapshots atomically.
  for entry in select value,n from jsonb_array_elements(p_input->'lines') with ordinality e(value,n) loop
   tax:=entry.value->'tax';
   if tax is null or tax='null'::jsonb then continue;end if;
   if jsonb_typeof(tax) is distinct from 'object' or not(tax ? 'exemption') then raise exception 'Invalid tax snapshot' using errcode='22023';end if;
   exemption:=tax->'exemption';
   if exemption<>'null'::jsonb and (jsonb_typeof(exemption) is distinct from 'object' or coalesce(exemption->>'issuedOn','') !~ '^[0-9]{4}-[0-9]{2}-[0-9]{2}$' or coalesce(exemption->>'rate','') !~ '^[0-9]{1,2}([.,][0-9]{1,2})?$') then raise exception 'Invalid exoneration date/rate' using errcode='22023';end if;
   insert into pro_invoice_line_tax(user_id,draft_id,line_number,vat_code,exemption_document_type,exemption_document_other,exemption_document_number,exemption_article,exemption_paragraph,exemption_institution,exemption_institution_other,exemption_issued_on,exemption_rate)
   values(p_user,saved,entry.n,tax->>'vatCode',exemption->>'documentType',exemption->>'documentOther',exemption->>'documentNumber',exemption->>'article',exemption->>'paragraph',exemption->>'institution',exemption->>'institutionOther',nullif(exemption->>'issuedOn','')::date,replace(exemption->>'rate',',','.')::numeric);
  end loop;
  select exists(select 1 from pro_invoice_line_tax where user_id=p_user and draft_id=saved) into has_tax;
  select * into gross_tax,exonerated from pro_invoice_tax_totals(p_user,saved);
  update pro_invoice_edited_detail set tax=gross_tax-exonerated,total=net+gross_tax-exonerated,calculation_version=case when has_tax then 'crc-draft-tax-v2' else 'crc-draft-v1' end where user_id=p_user and draft_id=saved;
  update pro_invoice_drafts d set tax_cents=round(h.tax*100),total_cents=round(h.total*100) from pro_invoice_edited_detail h where h.user_id=p_user and h.draft_id=saved and d.user_id=h.user_id and d.id=h.draft_id;
 end if;
 return saved;
end $$;
revoke all on function public.pro_invoice_line_tax_validate(),public.pro_invoice_tax_totals(uuid,uuid),public.pro_invoice_tax_read(uuid,uuid,jsonb),public.pro_invoice_tax_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_invoice_line_tax_validate(),public.pro_invoice_tax_totals(uuid,uuid),public.pro_invoice_tax_read(uuid,uuid,jsonb),public.pro_invoice_tax_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== invoice-extras-local.sql =====
-- LOCAL ONLY. Explicit line special taxes and independent draft charges; no issuance or historical backfill.
-- Install after invoice-tax-local.sql. All monetary calculations remain five-decimal commercial draft math.
begin;
alter table public.pro_invoice_edited_detail drop constraint if exists pro_invoice_edited_detail_calculation_version_check;
alter table public.pro_invoice_edited_detail add constraint pro_invoice_edited_detail_calculation_version_check check(calculation_version in ('crc-draft-v1','crc-draft-tax-v2','crc-draft-extras-v3','crc-draft-extras-v4'));
create table if not exists public.pro_invoice_line_special_tax(
 user_id uuid not null,draft_id uuid not null,line_number integer not null,tax_number integer not null check(tax_number between 1 and 3),
 code text not null check(code in ('03','06','12')),rate numeric,quantity_per_unit numeric,amount_per_unit numeric,
 primary key(user_id,draft_id,line_number,tax_number),unique(user_id,draft_id,line_number,code),
 foreign key(user_id,draft_id,line_number) references public.pro_invoice_edited_lines(user_id,draft_id,line_number) on delete cascade,
 check((code='12' and rate is not null and rate>0 and rate<=100 and rate=round(rate,2) and quantity_per_unit is null and amount_per_unit is null)
 or (code in ('03','06') and rate is null and quantity_per_unit is not null and quantity_per_unit>0 and quantity_per_unit<=99999.99 and quantity_per_unit=round(quantity_per_unit,2) and amount_per_unit is not null and amount_per_unit>0 and amount_per_unit<=100000000 and amount_per_unit=round(amount_per_unit,5)))
);
create table if not exists public.pro_invoice_draft_charges(
 user_id uuid not null,draft_id uuid not null,charge_number integer not null check(charge_number between 1 and 15),
 code text not null check(code in ('01','02','03','04','05','06','07','08','09','10','99')),
 other_detail text not null check(case when code='99' then length(trim(other_detail)) between 5 and 100 else other_detail='' end),
 description text not null check(length(trim(description)) between 1 and 160),
 mode text not null check(mode in ('amount','percent')),value numeric not null check(value>0 and value<=100000000 and value=round(value,5)),base numeric,
 third_party_id_type text,third_party_id text,third_party_name text,
 primary key(user_id,draft_id,charge_number),foreign key(user_id,draft_id) references public.pro_invoice_drafts(user_id,id) on delete cascade,
 check((mode='amount' and base is null) or (mode='percent' and value<=100 and base is not null and base>0 and base<=100000000 and base=round(base,5))),
 check(code<>'06' or (mode='percent' and value=10)),
 check(mode<>'percent' or round(base*value/100,5)>0),
 check((num_nonnulls(third_party_id_type,third_party_id,third_party_name)=0 and code<>'04') or (num_nulls(third_party_id_type,third_party_id,third_party_name)=0 and length(trim(third_party_name)) between 5 and 100 and case third_party_id_type when '01' then third_party_id ~ '^[1-9][0-9]{8}$' when '02' then third_party_id ~ '^[A-Za-z0-9]{10}$' when '03' then third_party_id ~ '^[1-9][0-9]{10,11}$' when '04' then third_party_id ~ '^[0-9]{10}$' else false end))
);
alter table public.pro_invoice_line_special_tax enable row level security;
alter table public.pro_invoice_draft_charges enable row level security;
drop policy if exists pro_invoice_line_special_tax_owner on public.pro_invoice_line_special_tax;
drop policy if exists pro_invoice_draft_charges_owner on public.pro_invoice_draft_charges;
create policy pro_invoice_line_special_tax_owner on public.pro_invoice_line_special_tax for select to authenticated using(user_id=(select auth.uid()));
create policy pro_invoice_draft_charges_owner on public.pro_invoice_draft_charges for select to authenticated using(user_id=(select auth.uid()));
revoke all on public.pro_invoice_line_special_tax,public.pro_invoice_draft_charges from public,anon,authenticated;
grant select on public.pro_invoice_line_special_tax,public.pro_invoice_draft_charges to authenticated;
grant all on public.pro_invoice_line_special_tax,public.pro_invoice_draft_charges to service_role;
create or replace function public.pro_invoice_extras_totals(p_user uuid,p_id uuid) returns table(gross_tax numeric,exonerated numeric,special_tax numeric,charge_total numeric)
language sql stable security invoker set search_path=public,pg_temp as $$
 with gross_lines as (select l.*,round(quantity*unit_price,5) as gross from pro_invoice_edited_lines l where user_id=p_user and draft_id=p_id),
 bases as (select *,gross-case when discount_type='percent' then round(gross*discount/100,5) else discount end as net from gross_lines),
 specials as (select t.line_number,t.code,case t.code when '12' then round(b.net*t.rate/100,5) when '03' then round(t.quantity_per_unit*t.amount_per_unit,5) when '06' then round(b.quantity*t.quantity_per_unit*t.amount_per_unit,5) end as amount from pro_invoice_line_special_tax t join bases b using(user_id,draft_id,line_number)),
 taxed as (select b.*,t.exemption_rate,b.net+coalesce((select sum(s.amount) from specials s where s.line_number=b.line_number and s.code='12'),0) as vat_base from bases b left join pro_invoice_line_tax t using(user_id,draft_id,line_number))
 select coalesce((select sum(case when tax_treatment='vat' then round(vat_base*tax_rate/100,5) else 0 end) from taxed),0),
 coalesce((select sum(case when exemption_rate is not null then round(vat_base*exemption_rate/100,5) else 0 end) from taxed),0),
 coalesce((select sum(amount) from specials),0),
 coalesce((select sum(case mode when 'amount' then value else round(base*value/100,5) end) from pro_invoice_draft_charges where user_id=p_user and draft_id=p_id),0);
$$;
create or replace function public.pro_invoice_extras_read(p_user uuid,p_id uuid,p_after jsonb default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare document jsonb;lines jsonb;charges jsonb;totals record;
begin
 document:=pro_invoice_tax_read(p_user,p_id,p_after);
 if document is null or not(exists(select 1 from pro_invoice_line_special_tax where user_id=p_user and draft_id=p_id) or exists(select 1 from pro_invoice_draft_charges where user_id=p_user and draft_id=p_id)) then return document;end if;
 select coalesce(jsonb_agg(jsonb_build_object('code',code,'otherDetail',other_detail,'description',description,'mode',mode,'value',value::text,'base',coalesce(base::text,''),'thirdParty',case when third_party_id_type is null then null else jsonb_build_object('idType',third_party_id_type,'id',third_party_id,'name',third_party_name) end) order by charge_number),'[]'::jsonb) into charges from pro_invoice_draft_charges where user_id=p_user and draft_id=p_id;
 document:=document||jsonb_build_object('charges',charges);
 if document->'editedDetail' is null or document->'editedDetail'='null'::jsonb then return document;end if;
 select jsonb_agg(e.value||case when e.value ? 'tax' then '{}'::jsonb else jsonb_build_object('tax',null) end||jsonb_build_object('specialTaxes',coalesce((select jsonb_agg(jsonb_build_object('code',s.code,'rate',coalesce(s.rate::text,''),'quantityPerUnit',coalesce(s.quantity_per_unit::text,''),'amountPerUnit',coalesce(s.amount_per_unit::text,'')) order by tax_number) from pro_invoice_line_special_tax s where s.user_id=p_user and s.draft_id=p_id and s.line_number=e.n),'[]'::jsonb)) order by e.n) into lines from jsonb_array_elements(document->'editedDetail'->'lines') with ordinality e(value,n);
 select * into totals from pro_invoice_extras_totals(p_user,p_id);
 return jsonb_set(document,'{editedDetail}',document->'editedDetail'||jsonb_build_object('lines',lines,'grossTax',round(totals.gross_tax,5)::text,'exonerated',round(totals.exonerated,5)::text,'specialTax',round(totals.special_tax,5)::text,'chargeTotal',round(totals.charge_total,5)::text,'version','crc-draft-extras-v3'));
end $$;
create or replace function public.pro_invoice_extras_save(p_user uuid,p_input jsonb) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare saved uuid;target uuid;action text:=p_input->>'action';line record;special record;charge record;third jsonb;totals record;old_charges numeric;has_extras boolean;has_vat boolean;had_detail boolean;
begin
 perform pg_advisory_xact_lock(hashtextextended(p_user::text,0));
 if action='create_direct' then
  target:=(p_input->>'requestId')::uuid;
  if exists(select 1 from pro_invoice_drafts where user_id=p_user and id=target) then return pro_invoice_tax_save(p_user,p_input);end if;
 elsif action in ('detail','refresh','reset_detail','update') then target:=(p_input->>'id')::uuid;end if;
 if action='detail' then
  if exists(select 1 from pro_invoice_line_special_tax where user_id=p_user and draft_id=target) and exists(select 1 from jsonb_array_elements(p_input->'lines') e where not(e ? 'specialTaxes')) then raise exception 'This editor cannot preserve saved special taxes; reload' using errcode='40001';end if;
  if exists(select 1 from pro_invoice_draft_charges where user_id=p_user and draft_id=target) and not(p_input ? 'charges') then raise exception 'This editor cannot preserve saved charges; reload' using errcode='40001';end if;
 end if;
 -- A reset leaves charges independent of the edited detail. Never feed them back into a source snapshot.
 if action in ('detail','refresh') and not exists(select 1 from pro_invoice_edited_detail where user_id=p_user and draft_id=target) then
  select charge_total into old_charges from pro_invoice_extras_totals(p_user,target);
  if old_charges>0 then update pro_invoice_drafts set total_cents=total_cents-round(old_charges*100) where user_id=p_user and id=target;end if;
 end if;
 select exists(select 1 from pro_invoice_edited_detail where user_id=p_user and draft_id=target) into had_detail;
 saved:=pro_invoice_tax_save(p_user,p_input);
 if action='reset_detail' and not had_detail then return saved;end if;
 if action in ('detail','create_direct') then
  for line in select value,n from jsonb_array_elements(p_input->'lines') with ordinality e(value,n) loop
   if not(line.value ? 'specialTaxes') then continue;end if;
   if jsonb_typeof(line.value->'specialTaxes') is distinct from 'array' or jsonb_array_length(line.value->'specialTaxes')>3 then raise exception 'Invalid special taxes' using errcode='22023';end if;
   for special in select value,n from jsonb_array_elements(line.value->'specialTaxes') with ordinality e(value,n) loop
    insert into pro_invoice_line_special_tax(user_id,draft_id,line_number,tax_number,code,rate,quantity_per_unit,amount_per_unit) values(p_user,saved,line.n,special.n,special.value->>'code',replace(nullif(special.value->>'rate',''),',','.')::numeric,replace(nullif(special.value->>'quantityPerUnit',''),',','.')::numeric,replace(nullif(special.value->>'amountPerUnit',''),',','.')::numeric);
   end loop;
  end loop;
  if p_input ? 'charges' then
   if jsonb_typeof(p_input->'charges') is distinct from 'array' or jsonb_array_length(p_input->'charges')>15 then raise exception 'Invalid charges' using errcode='22023';end if;
   delete from pro_invoice_draft_charges where user_id=p_user and draft_id=saved;
   for charge in select value,n from jsonb_array_elements(p_input->'charges') with ordinality e(value,n) loop
    third:=charge.value->'thirdParty';
    if third is null or (third<>'null'::jsonb and jsonb_typeof(third)<>'object') then raise exception 'Invalid third party' using errcode='22023';end if;
    insert into pro_invoice_draft_charges(user_id,draft_id,charge_number,code,other_detail,description,mode,value,base,third_party_id_type,third_party_id,third_party_name) values(p_user,saved,charge.n,charge.value->>'code',charge.value->>'otherDetail',charge.value->>'description',charge.value->>'mode',replace(charge.value->>'value',',','.')::numeric,replace(nullif(charge.value->>'base',''),',','.')::numeric,third->>'idType',third->>'id',third->>'name');
   end loop;
  end if;
 end if;
 -- Updates only change receiver/preparation/title; their already adjusted totals remain untouched.
 if action in ('detail','create_direct','refresh','reset_detail') then
  select * into totals from pro_invoice_extras_totals(p_user,saved);
  select exists(select 1 from pro_invoice_line_special_tax where user_id=p_user and draft_id=saved) or exists(select 1 from pro_invoice_draft_charges where user_id=p_user and draft_id=saved) into has_extras;
  select exists(select 1 from pro_invoice_line_tax where user_id=p_user and draft_id=saved) into has_vat;
  if exists(select 1 from pro_invoice_edited_detail where user_id=p_user and draft_id=saved) then
   if exists(select 1 from pro_invoice_edited_detail where user_id=p_user and draft_id=saved and round((net+totals.gross_tax+totals.special_tax+totals.charge_total)*100)>10000000000) then raise exception 'Draft before-exoneration total exceeds limit' using errcode='22023';end if;
   update pro_invoice_edited_detail set tax=totals.gross_tax-totals.exonerated,total=net+totals.gross_tax-totals.exonerated+totals.special_tax+totals.charge_total,calculation_version=case when has_extras then 'crc-draft-extras-v3' when has_vat then 'crc-draft-tax-v2' else 'crc-draft-v1' end where user_id=p_user and draft_id=saved;
   update pro_invoice_drafts d set total_cents=round(h.total*100),tax_cents=round((h.tax+totals.special_tax)*100) from pro_invoice_edited_detail h where h.user_id=p_user and h.draft_id=saved and d.user_id=h.user_id and d.id=h.draft_id;
  elsif totals.charge_total>0 then
   -- The legacy refresh/reset restored the source amount. Its tax NULL remains unknown, not invented zero.
   update pro_invoice_drafts set total_cents=total_cents+round(totals.charge_total*100) where user_id=p_user and id=saved;
  end if;
 end if;
 return saved;
end $$;
revoke all on function public.pro_invoice_extras_totals(uuid,uuid),public.pro_invoice_extras_read(uuid,uuid,jsonb),public.pro_invoice_extras_save(uuid,jsonb) from public,anon,authenticated;
grant execute on function public.pro_invoice_extras_totals(uuid,uuid),public.pro_invoice_extras_read(uuid,uuid,jsonb),public.pro_invoice_extras_save(uuid,jsonb) to service_role;
notify pgrst,'reload schema';
commit;
